        return VStack(alignment: .leading, spacing: 12) {
            Text("Start where you left off")
                .font(.title2.weight(.semibold))

            ViewThatFits(in: .horizontal) {
                HStack(alignment: .top, spacing: 12) {
                    leftOffCard(
                        title: "Next task",
                        value: snapshot?.nextTaskTitle ?? "Add a review, exercise, or reading task.",
                        systemImage: "checklist"
                    )
                    leftOffCard(
                        title: "Recent notes",
                        value: snapshot?.notesPreview ?? "Session notes will appear here after you study.",
                        systemImage: "note.text"
                    )
                    leftOffCard(
                        title: "This week",
                        value: DurationFormatter.minutes(progress.weekMinutes),
                        systemImage: "calendar"
                    )
                }
                VStack(alignment: .leading, spacing: 12) {
                    leftOffCard(
                        title: "Next task",
                        value: snapshot?.nextTaskTitle ?? "Add a review, exercise, or reading task.",
                        systemImage: "checklist"
                    )
                    leftOffCard(
                        title: "Recent notes",
                        value: snapshot?.notesPreview ?? "Session notes will appear here after you study.",
                        systemImage: "note.text"
                    )
                    leftOffCard(
                        title: "This week",
                        value: DurationFormatter.minutes(progress.weekMinutes),
                        systemImage: "calendar"
                    )
                }
            }
        }
    }

    private func leftOffCard(title: String, value: String, systemImage: String) -> some View {
        VStack(alignment: .leading, spacing: 8) {
            Label(title, systemImage: systemImage)
                .font(.caption.weight(.semibold))
                .foregroundStyle(.secondary)
            Text(value)
                .font(.callout)
                .lineLimit(2)
        }
        .padding(12)
        .frame(maxWidth: .infinity, minHeight: 86, alignment: .topLeading)
        .background(.quaternary.opacity(0.18), in: RoundedRectangle(cornerRadius: 8))
    }

    private var detailsGrid: some View {
        Grid(alignment: .leading, horizontalSpacing: 28, verticalSpacing: 14) {
            detailRow("Tasks", "\(box.tasks.count)")
            detailRow("Resources", "\(box.resources.count)")
            detailRow("Sessions", "\(box.sessions.count)")
            detailRow("Saved windows", "\(box.windowLayouts.count)")
            detailRow("Default session", DurationFormatter.minutes(box.defaultSessionMinutes))
            detailRow("Open resources on start", box.openResourcesOnSessionStart ? "On" : "Off")
            detailRow("Hide unrelated apps", box.hideDistractionsOnSessionStart ? "On" : "Off")
            detailRow("Ask apps to quit", box.quitDistractionsOnSessionStart ? "On" : "Off")
            detailRow("Block new distractions", box.enforceFocusOnSessionStart ? "On" : "Off")
            detailRow("Restore saved layout", box.restoreWindowLayoutOnSessionStart ? "On" : "Off")
            detailRow("Keep display awake", (box.keepDisplayAwakeDuringSessions ?? true) ? "On" : "Off")
            detailRow("Created", box.createdAt.formatted(date: .abbreviated, time: .shortened))
            detailRow("Updated", box.updatedAt.formatted(date: .abbreviated, time: .shortened))
        }
    }

    private func detailRow(_ label: String, _ value: String) -> some View {
        GridRow {
            Text(label)
                .foregroundStyle(.secondary)
            Text(value)
        }
    }

    private func save() {
        do {
            try modelContext.save()
        } catch {
            assertionFailure("Failed to save StudyBox changes: \(error)")
        }
    }

    private func captureLayout() {
        guard PermissionManager.isAccessibilityTrusted else {
            showingAccessibilityHelp = true
            return
        }

        do {
            let count = try WindowLayoutManager.captureLayout(for: box, modelContext: modelContext)
            layoutMessage = count == 1 ? "Captured 1 window." : "Captured \(count) windows."
        } catch {
            layoutMessage = "Could not capture this layout."
        }
    }

    private func exportThisBox() {
        guard let url = FilePicker.chooseJSONExport(defaultName: "\(box.name) Study Box.json") else { return }
        do {
            try BackupService.export(boxes: [box], to: url)
            layoutMessage = "Exported \(box.name)."
        } catch {
            layoutMessage = "Could not export this Study Box."
        }
    }
}

// MARK: - StudyBoxes/Views/Boxes/BoxEditorView.swift

import SwiftData
import SwiftUI

struct BoxEditorView: View {
    @Environment(\.dismiss) private var dismiss
    @Environment(\.modelContext) private var modelContext

    private let box: StudyBox?

    @State private var name: String
    @State private var type: StudyBoxType
    @State private var courseName: String
    @State private var icon: String
    @State private var colorHex: String
    @State private var hasExamDate: Bool
    @State private var examDate: Date
    @State private var defaultSessionMinutes: Int
    @State private var defaultSessionMinutesText: String
    @State private var openResourcesOnSessionStart: Bool
    @State private var hideDistractionsOnSessionStart: Bool
    @State private var quitDistractionsOnSessionStart: Bool
    @State private var enforceFocusOnSessionStart: Bool
    @State private var restoreWindowLayoutOnSessionStart: Bool
    @State private var keepDisplayAwakeDuringSessions: Bool
    @State private var errorMessage: String?

    private let icons = [
        "books.vertical",
        "graduationcap",
        "function",
        "sum",
        "atom",
        "desktopcomputer",
        "doc.text",
        "calendar"
    ]

    private let colors = [
        "#3B82F6",
        "#14B8A6",
        "#22C55E",
        "#F59E0B",
        "#EF4444",
        "#A855F7",
        "#64748B"
    ]

    init(box: StudyBox? = nil) {
        self.box = box
        _name = State(initialValue: box?.name ?? "")
        _type = State(initialValue: box?.type ?? .course)
        _courseName = State(initialValue: box?.courseName ?? "")
        _icon = State(initialValue: box?.icon ?? "books.vertical")
        _colorHex = State(initialValue: box?.colorHex ?? "#3B82F6")
        _hasExamDate = State(initialValue: box?.examDate != nil)
        _examDate = State(initialValue: box?.examDate ?? .now)
        _defaultSessionMinutes = State(initialValue: box?.defaultSessionMinutes ?? 50)
        _defaultSessionMinutesText = State(initialValue: String(box?.defaultSessionMinutes ?? 50))
        _openResourcesOnSessionStart = State(initialValue: box?.openResourcesOnSessionStart ?? true)
        _hideDistractionsOnSessionStart = State(initialValue: box?.hideDistractionsOnSessionStart ?? false)
        _quitDistractionsOnSessionStart = State(initialValue: box?.quitDistractionsOnSessionStart ?? false)
        _enforceFocusOnSessionStart = State(initialValue: box?.enforceFocusOnSessionStart ?? false)
        _restoreWindowLayoutOnSessionStart = State(initialValue: box?.restoreWindowLayoutOnSessionStart ?? false)
        _keepDisplayAwakeDuringSessions = State(initialValue: box?.keepDisplayAwakeDuringSessions ?? true)
    }

    var body: some View {
        VStack(alignment: .leading, spacing: 0) {
            Form {
                Section("Study Box") {
                    TextField("Name", text: $name)

                    Picker("Type", selection: $type) {
                        ForEach(StudyBoxType.allCases) { type in
                            Text(type.title).tag(type)
                        }
                    }

                    TextField("Course name", text: $courseName)
                }

                Section("Appearance") {
                    Picker("Icon", selection: $icon) {
                        ForEach(icons, id: \.self) { iconName in
                            Label(iconName, systemImage: iconName).tag(iconName)
                        }
                    }

                    HStack {
                        Text("Color")
                        Spacer()
                        ForEach(colors, id: \.self) { color in
                            Button {
                                colorHex = color
                            } label: {
                                Circle()
                                    .fill(Color(hex: color))
                                    .frame(width: 22, height: 22)
                                    .overlay {
                                        if colorHex == color {
                                            Circle()
                                                .stroke(.primary, lineWidth: 2)
                                        }
                                    }
                            }
                            .buttonStyle(.plain)
                        }
                    }
                }

                Section("Planning") {
                    Toggle("Exam or deadline date", isOn: $hasExamDate)

                    if hasExamDate {
                        DatePicker(
                            "Date",
                            selection: $examDate,
                            displayedComponents: .date
                        )
                    }

                    HStack {
                        Text("Session presets")
                        Spacer()
                        ForEach(SessionPreset.defaultMinutes, id: \.self) { minutes in
                            Button("\(minutes)") {
                                defaultSessionMinutesText = String(minutes)
                                defaultSessionMinutes = minutes
                            }
                            .controlSize(.small)
                        }
                    }

                    HStack {
                        Text("Default session length")
                        Spacer()
                        HStack(spacing: 6) {
                            TextField("0", text: $defaultSessionMinutesText)
                                .frame(width: 56)
                                .multilineTextAlignment(.trailing)
                                .textFieldStyle(.roundedBorder)
                            Text("min")
                                .foregroundStyle(.secondary)
                        }
                    }
                    .help("You can type any whole-minute session length up to 999 minutes.")
                    .onChange(of: defaultSessionMinutesText) { _, newValue in
                        let sanitized = NumericInput.sanitizedIntegerText(newValue, range: 0...999)
                        if sanitized != newValue {
                            defaultSessionMinutesText = sanitized
                        }
                        defaultSessionMinutes = NumericInput.integerValue(from: sanitized, fallback: defaultSessionMinutes, range: 0...999)
                    }
                }

                Section("Session Start") {
                    Toggle("Open enabled resources", isOn: $openResourcesOnSessionStart)
                    Toggle("Hide unrelated apps", isOn: $hideDistractionsOnSessionStart)
                    Toggle("Ask unrelated apps to quit", isOn: $quitDistractionsOnSessionStart)
                    Toggle("Block newly opened distractions", isOn: $enforceFocusOnSessionStart)
                    Toggle("Restore saved window layout", isOn: $restoreWindowLayoutOnSessionStart)
                    Toggle("Keep display awake", isOn: $keepDisplayAwakeDuringSessions)

                    Text("Focus controls work at the app level. Hide moves apps out of view. Quit politely asks apps to close and may show save prompts. Strict Focus blocks newly opened unrelated apps. Study Boxes never force quits or inspects browser tabs.")
                        .font(.caption)
                        .foregroundStyle(.secondary)
                }

                if let errorMessage {
                    Text(errorMessage)
                        .foregroundStyle(.red)
                }
            }
            .formStyle(.grouped)

            Divider()

            HStack {
                Spacer()

                Button("Cancel") {
                    dismiss()
                }

                Button(box == nil ? "Create" : "Save") {
                    save()
                }
                .keyboardShortcut(.defaultAction)
            }
            .padding()
        }
    }

    private func save() {
        let trimmedName = name.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmedName.isEmpty else {
            errorMessage = "Name is required."
            return
        }

        let trimmedCourseName = courseName.trimmingCharacters(in: .whitespacesAndNewlines)
        let storedCourseName = trimmedCourseName.isEmpty ? nil : trimmedCourseName
        let storedExamDate = hasExamDate ? examDate : nil
        let storedDefaultSessionMinutes = NumericInput.integerValue(
            from: defaultSessionMinutesText,
            fallback: defaultSessionMinutes,
            range: 0...999
        )

        if let box {
            box.update(
                name: trimmedName,
                type: type,
                courseName: storedCourseName,
                icon: icon,
                colorHex: colorHex,
                examDate: storedExamDate,
                defaultSessionMinutes: storedDefaultSessionMinutes,
                openResourcesOnSessionStart: openResourcesOnSessionStart,
                hideDistractionsOnSessionStart: hideDistractionsOnSessionStart,
                quitDistractionsOnSessionStart: quitDistractionsOnSessionStart,
                enforceFocusOnSessionStart: enforceFocusOnSessionStart,
                restoreWindowLayoutOnSessionStart: restoreWindowLayoutOnSessionStart,
                keepDisplayAwakeDuringSessions: keepDisplayAwakeDuringSessions
            )
        } else {
            let box = StudyBox(
                name: trimmedName,
                type: type,
                courseName: storedCourseName,
                icon: icon,
                colorHex: colorHex,
                examDate: storedExamDate,
                hideDistractionsOnSessionStart: hideDistractionsOnSessionStart,
                quitDistractionsOnSessionStart: quitDistractionsOnSessionStart,
                enforceFocusOnSessionStart: enforceFocusOnSessionStart,
                restoreWindowLayoutOnSessionStart: restoreWindowLayoutOnSessionStart,
                openResourcesOnSessionStart: openResourcesOnSessionStart,
                keepDisplayAwakeDuringSessions: keepDisplayAwakeDuringSessions,
                defaultSessionMinutes: storedDefaultSessionMinutes
            )
            modelContext.insert(box)
        }

        do {
            try modelContext.save()
            dismiss()
        } catch {
            errorMessage = "Could not save this Study Box."
        }
    }
}

// MARK: - StudyBoxes/Views/Boxes/BoxListView.swift

import SwiftData
import SwiftUI

struct BoxListView: View {
    @Environment(\.modelContext) private var modelContext
    @Binding var selectedBoxID: UUID?

    @Query(sort: \StudyBox.updatedAt, order: .reverse)
    private var boxes: [StudyBox]

    @State private var isCreatingBox = false
    @State private var showsArchived = false

    private var visibleBoxes: [StudyBox] {
        boxes.filter { showsArchived ? $0.isArchived : !$0.isArchived }
    }

    var body: some View {
        VStack(spacing: 0) {
            List(selection: $selectedBoxID) {
                Section {
                    Label("Home", systemImage: "house")
                        .tag(Optional<UUID>.none)
                }

                Section(showsArchived ? "Archived" : "Active") {
                    ForEach(visibleBoxes) { box in
                        BoxListRow(box: box)
                            .tag(Optional(box.id))
                            .contextMenu {
                                if box.isArchived {
                                    Button("Restore") {
                                        box.restore()
                                        save()
                                    }
                                } else {
                                    Button("Archive") {
                                        box.archive()
                                        save()
                                    }
                                }

                                Button("Delete", role: .destructive) {
                                    delete(box)
                                }
                            }
                    }
                }
            }

            Divider()

            HStack {
                Toggle("Archived", isOn: $showsArchived)
                    .toggleStyle(.switch)

                Spacer()

                Button {
                    isCreatingBox = true
                } label: {
                    Label("New", systemImage: "plus")
                }
            }
            .padding(12)
        }
        .toolbar {
            ToolbarItem(placement: .primaryAction) {
                Button {
                    isCreatingBox = true
                } label: {
                    Label("New Study Box", systemImage: "plus")
                }
            }
        }
        .sheet(isPresented: $isCreatingBox) {
            BoxEditorView()
                .frame(minWidth: 460)
        }
    }

    private func delete(_ box: StudyBox) {
        if selectedBoxID == box.id {
            selectedBoxID = nil
        }
        modelContext.delete(box)
        save()
    }

    private func save() {
        do {
            try modelContext.save()
        } catch {
            assertionFailure("Failed to save StudyBox changes: \(error)")
        }
    }
}

private struct BoxListRow: View {
    let box: StudyBox

    var body: some View {
        Label {
            VStack(alignment: .leading, spacing: 3) {
                Text(box.name)
                    .font(.headline)
                    .lineLimit(1)

                Text(subtitle)
                    .font(.caption)
                    .foregroundStyle(.secondary)
                    .lineLimit(1)
            }
        } icon: {
            Image(systemName: box.icon)
                .foregroundStyle(Color(hex: box.colorHex))
        }
        .padding(.vertical, 4)
    }

    private var subtitle: String {
        if let courseName = box.courseName, !courseName.isEmpty {
            return "\(box.type.title) - \(courseName)"
        }
        return box.type.title
    }
}

// MARK: - StudyBoxes/Views/Dashboard/DashboardView.swift

import SwiftData
import SwiftUI

struct DashboardView: View {
    @Environment(\.openWindow) private var openWindow
    @Environment(\.openSettings) private var openSettings
    @EnvironmentObject private var appState: AppState
    @Environment(\.modelContext) private var modelContext

    @Query(sort: \StudyBox.updatedAt, order: .reverse)
    private var boxes: [StudyBox]

    @Query(sort: \StudySession.startedAt, order: .reverse)
    private var sessions: [StudySession]

    @State private var selectedBoxID: UUID?
    @State private var launchResults: [ResourceLaunchResult] = []
    @State private var showingIntegrations = false
    @State private var notificationMessage: String?
    @State private var isShowingOnboarding = false
    @State private var resumeMinutesText = ""
    @StateObject private var onboardingState = OnboardingState.shared

    private var activeBoxes: [StudyBox] {
        boxes.filter { !$0.isArchived }
    }

    private var selectedBox: StudyBox? {
        guard let selectedBoxID else { return nil }
        return activeBoxes.first { $0.id == selectedBoxID }
    }

    private var todayTasks: [StudyTask] {
        TaskManager.filteredTasks(activeBoxes.flatMap(\.tasks), filter: .today)
    }

    private var upcomingDeadlines: [StudyTask] {
        TaskManager.sorted(activeBoxes.flatMap(\.tasks).filter { task in
            guard task.status != .done, let dueDate = task.dueDate else { return false }
            return dueDate >= Calendar.current.startOfDay(for: .now)
        })
    }

    private var activeSession: StudySession? {
        guard let activeSessionID = appState.activeSessionID else { return nil }
        return sessions.first { $0.id == activeSessionID }
    }

    private var resumeBox: StudyBox? {
        StudyResumeService.mostRecentlyStudiedBox(from: activeBoxes, sessions: sessions)
    }

    var body: some View {
        NavigationSplitView {
            BoxListView(selectedBoxID: $selectedBoxID)
                .navigationSplitViewColumnWidth(min: 240, ideal: 280)
        } detail: {
            if let activeSession, let box = activeSession.box {
                SessionModeView(
                    box: box,
                    session: activeSession,
                    launchResults: appState.activeLaunchResults,
                    onNotesChanged: { notes in
                        activeSession.notes = notes
                    }
                )
                .environmentObject(appState)
                .frame(maxWidth: .infinity, maxHeight: .infinity, alignment: .topLeading)
            } else if let selectedBox {
                ScrollView {
                    VStack(alignment: .leading, spacing: 24) {
                        dashboardOverview
                        BoxDetailView(box: selectedBox)
                    }
                    .padding(32)
                    .frame(maxWidth: 1180, alignment: .leading)
                }
                .frame(maxWidth: .infinity, alignment: .topLeading)
            } else if !activeBoxes.isEmpty {
                ScrollView {
                    VStack(alignment: .leading, spacing: 24) {
                        dashboardOverview
                        activeBoxesOverview
                    }
                    .padding(32)
                    .frame(maxWidth: 1180, alignment: .leading)
                }
                .frame(maxWidth: .infinity, alignment: .topLeading)
            } else {
                ContentUnavailableView(
                    "Create your first Study Box",
                    systemImage: "books.vertical",
                    description: Text("Collect one course, exam, assignment, or topic into a launchable study setup.")
                )
            }
        }
        .frame(minWidth: 860, minHeight: 620)
        .toolbar {
            ToolbarItemGroup(placement: .primaryAction) {
                Button {
                    showingIntegrations = true
                } label: {
                    Label("Import Deadlines", systemImage: "calendar.badge.plus")
                }
                .help("Add or sync Moodle, Blackboard, or ICS calendar feeds.")

	                Button {
	                    Task {
	                        let result = await NotificationService.scheduleDeadlineReminders(for: boxes)
	                        notificationMessage = result.message
	                    }
                } label: {
                    Label("Schedule Reminders", systemImage: "bell")
                }
                .help("Ask for notification permission if needed, then schedule reminders for Study Box dates and task due dates.")

                Button {
                    openSettings()
                } label: {
                    Label("Settings", systemImage: "gearshape")
                }
                .help("Open Study Boxes settings.")
            }
        }
        .onAppear {
            selectedBoxID = nil
            if onboardingState.hasCompletedOnboarding {
                isShowingOnboarding = false
            } else if boxes.isEmpty {
                isShowingOnboarding = true
            } else {
                onboardingState.complete()
            }
        }
        .onChange(of: activeBoxes.map(\.id)) {
            if selectedBoxID == nil {
                return
            }
            if let selectedBoxID, activeBoxes.contains(where: { $0.id == selectedBoxID }) {
                return
            }
            selectedBoxID = nil
        }
        .onReceive(appState.$activeBoxID.compactMap { $0 }) { boxID in
            selectedBoxID = boxID
        }
        .onReceive(appState.$activeSessionID) { activeSessionID in
            if activeSessionID == nil {
                launchResults = []
            }
        }
        .onReceive(appState.$isIntegrationsPresented) { isPresented in
            if isPresented {
                showingIntegrations = true
            }
        }
        .sheet(isPresented: $appState.isSessionSetupPresented) {
            if let boxID = appState.activeBoxID,
               let box = boxes.first(where: { $0.id == boxID }) {
                SessionSetupView(box: box) { options in
                    startStudySession(for: box, options: options)
                }
            } else {
                ContentUnavailableView(
                    "Choose a Study Box",
                    systemImage: "books.vertical",
                    description: Text("Select a Study Box before starting a session.")
                )
                .frame(minWidth: 420, minHeight: 260)
            }
        }
        .sheet(isPresented: $showingIntegrations) {
            LMSIntegrationsView()
                .onDisappear {
                    appState.isIntegrationsPresented = false
                }
        }
        .sheet(isPresented: $isShowingOnboarding) {
            OnboardingView { box, startImmediately in
                guard startImmediately, let box else { return }
                startStudySession(for: box, options: defaultSessionOptions(for: box))
            }
            .environmentObject(appState)
        }
        .overlay(alignment: .bottom) {
            if let notificationMessage {
                Text(notificationMessage)
                    .font(.caption)
                    .padding(10)
                    .background(.regularMaterial, in: RoundedRectangle(cornerRadius: 8))
                    .padding(.bottom, 12)
            }
        }
    }

