    @ViewBuilder
    private func resumeDescription(for box: StudyBox) -> some View {
        if let snapshot = StudyResumeService.snapshot(for: box, sessions: sessions) {
            VStack(alignment: .leading, spacing: 5) {
                Text("\(box.name) · last studied \(snapshot.lastStudiedAt.formatted(date: .abbreviated, time: .shortened))")
