                    .font(.caption)
                    .foregroundStyle(.secondary)
                Text(value)
                    .font(.headline)
            }
            Spacer()
        }
        .padding(12)
        .frame(maxWidth: .infinity, alignment: .leading)
        .background(.quaternary.opacity(0.18), in: RoundedRectangle(cornerRadius: 8))
    }

    private func sessionPresetControls(text: Binding<String>, defaultMinutes: Int) -> some View {
        HStack(spacing: 6) {
            ForEach(SessionPreset.defaultMinutes, id: \.self) { minutes in
                Button("\(minutes)") {
                    text.wrappedValue = String(minutes)
                }
                .controlSize(.small)
            }
            TextField(String(defaultMinutes), text: text)
                .frame(width: 52)
                .multilineTextAlignment(.trailing)
                .textFieldStyle(.roundedBorder)
                .onChange(of: text.wrappedValue) { _, newValue in
                    let sanitized = NumericInput.sanitizedIntegerText(newValue, range: 0...999)
                    if sanitized != newValue {
                        text.wrappedValue = sanitized
                    }
                }
            Text("min")
                .font(.caption)
                .foregroundStyle(.secondary)
        }
    }

    private func overviewPanel<Content: View>(
        title: String,
        systemImage: String,
        emptyText: String,
        isEmpty: Bool,
        @ViewBuilder content: () -> Content
    ) -> some View {
        VStack(alignment: .leading, spacing: 12) {
            Label(title, systemImage: systemImage)
                .font(.headline)

            if isEmpty {
                Text(emptyText)
                    .foregroundStyle(.secondary)
            } else {
                content()
            }
        }
        .padding(14)
        .frame(maxWidth: .infinity, minHeight: 120, alignment: .topLeading)
        .background(.quaternary.opacity(0.2), in: RoundedRectangle(cornerRadius: 8))
    }

    private func overviewTaskLabel(_ task: StudyTask) -> some View {
        VStack(alignment: .leading, spacing: 3) {
            Text(task.title)
                .font(.callout.weight(.medium))
                .lineLimit(1)
            HStack(spacing: 8) {
                if let boxName = task.box?.name {
                    Text(boxName)
                }
                if let dueDate = task.dueDate {
                    Text(dueDate.formatted(date: .abbreviated, time: .omitted))
                }
            }
            .font(.caption)
            .foregroundStyle(.secondary)
        }
        .frame(maxWidth: .infinity, alignment: .leading)
    }

    private func startStudySession(for box: StudyBox, options: SessionStartOptions) {
        guard appState.activeSessionID == nil, !appState.isStartingSession else { return }

        appState.isStartingSession = true
        appState.isSessionSetupPresented = false
        appState.isSessionModePresented = true

        let session = SessionManager.startSession(
            for: box,
            options: options,
            modelContext: modelContext
        )

        launchResults = []
        appState.registerStartedSession(session, box: box, options: options, launchResults: [])
        selectedBoxID = nil

        guard options.openResources || options.restoreWindowLayout else {
            return
        }

        Task {
            let report = await SessionManager.finishStartup(for: box, options: options)
            guard appState.activeSessionID == session.id else { return }
            launchResults = report.launchResults
            appState.updateStartupReport(report)
        }
    }

    private func defaultSessionOptions(for box: StudyBox) -> SessionStartOptions {
        SessionStartOptions(
            plannedMinutes: box.defaultSessionMinutes,
            openResources: box.openResourcesOnSessionStart,
            hideDistractions: box.hideDistractionsOnSessionStart,
            quitDistractions: box.quitDistractionsOnSessionStart,
            enforceFocus: box.enforceFocusOnSessionStart,
            restoreWindowLayout: box.restoreWindowLayoutOnSessionStart,
            keepDisplayAwake: box.keepDisplayAwakeDuringSessions ?? true
        )
    }

    private func resumeSessionOptions(for box: StudyBox) -> SessionStartOptions {
        var options = defaultSessionOptions(for: box)
        options.plannedMinutes = NumericInput.integerValue(
            from: resumeMinutesText,
            fallback: box.defaultSessionMinutes,
            range: 0...999
        )
        return options
    }
}

// MARK: - StudyBoxes/Views/Integrations/ICSFeedEditorView.swift

import SwiftData
import SwiftUI

struct ICSFeedEditorView: View {
    @Environment(\.dismiss) private var dismiss
    @Environment(\.modelContext) private var modelContext

    @State private var provider: LMSProvider = .genericICS
    @State private var title = ""
    @State private var feedURL = ""
    @State private var errorMessage: String?

    var body: some View {
        VStack(alignment: .leading, spacing: 0) {
            Form {
	                Section("Feed") {
	                    Picker("Provider", selection: $provider) {
	                        ForEach(LMSProvider.allCases) { provider in
	                            Text(provider.title).tag(provider)
	                        }
	                    }
	                    .help("This labels the feed. Study Boxes still imports it as a standard ICS calendar.")

	                    TextField("Name", text: $title)
	                        .help("A name like Moodle deadlines or Operating Systems calendar.")
	                    TextField("Calendar feed URL", text: $feedURL)
	                        .help("Paste the full private calendar export URL, including query parameters and tokens.")
	                }

	                Text("Calendar feed links can contain private tokens. Study Boxes stores the link in Keychain and keeps only a lookup key in SwiftData.")
	                    .font(.caption)
	                    .foregroundStyle(.secondary)
	                Text("After saving, press Sync Deadlines to fetch events and convert them into Study Box tasks.")
	                    .font(.caption)
	                    .foregroundStyle(.secondary)

                if let errorMessage {
                    Text(errorMessage)
                        .foregroundStyle(.red)
                }
            }
            .formStyle(.grouped)

            Divider()

            HStack {
                Spacer()
                Button("Cancel") { dismiss() }
	                Button("Save Feed") { save() }
	                    .keyboardShortcut(.defaultAction)
            }
            .padding()
        }
    }

    private func save() {
        let trimmedTitle = title.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmedTitle.isEmpty else {
            errorMessage = "Name is required."
            return
        }

        do {
            _ = try ICSFeedService.addFeed(title: trimmedTitle, provider: provider, feedURL: feedURL, modelContext: modelContext)
            dismiss()
        } catch {
            errorMessage = error.localizedDescription
        }
    }
}

