	                ForEach(boxes) { box in
	                    Button(box.name) {
	                        onConvert(box)
	                    }
	                }
	            }
	            .disabled(boxes.isEmpty || event.mappedTaskID != nil)
	            .help("Create a Study Box task from this imported deadline.")

            Button(event.ignored ? "Restore" : "Ignore") {
                event.ignored.toggle()
                event.updatedAt = .now
                onSave()
            }
            .help(event.ignored ? "Show this event again." : "Hide this event from the active imported event list.")
	        }
	    }
}

// MARK: - StudyBoxes/Views/MenuBar/MenuBarRootView.swift

import AppKit
import SwiftData
import SwiftUI

struct MenuBarRootView: View {
    @Environment(\.openWindow) private var openWindow
    @Environment(\.openSettings) private var openSettings
    @Environment(\.modelContext) private var modelContext
    @EnvironmentObject private var appState: AppState

    @Query(sort: \StudyBox.updatedAt, order: .reverse)
    private var boxes: [StudyBox]

    @Query(sort: \StudySession.startedAt, order: .reverse)
    private var sessions: [StudySession]

    @State private var isAddingSessionTask = false
    @State private var menuLaunchMessage: String?

    private var activeBoxes: [StudyBox] {
        boxes.filter { !$0.isArchived }
    }

    private var activeSession: StudySession? {
        guard let activeSessionID = appState.activeSessionID else { return nil }
        return sessions.first { $0.id == activeSessionID }
    }

    private var activeSessionTasks: [StudyTask] {
        guard let activeSession, let box = activeSession.box else { return [] }
        return TaskManager.sorted(box.tasks.filter { $0.status != .done })
    }

    private var resumeBox: StudyBox? {
        StudyResumeService.mostRecentlyStudiedBox(from: activeBoxes, sessions: sessions)
    }

    var body: some View {
        if let startedAt = appState.activeSessionStartedAt {
            TimelineView(.periodic(from: startedAt, by: 1)) { context in
                Text("\(appState.activeSessionBoxName ?? "Study Box") - \(DurationFormatter.clock(context.date.timeIntervalSince(startedAt)))")
            }
            if appState.isHidingDistractionsActive {
                Text("Focus controls active")
            }
            if appState.isFocusEnforcementActive {
                Text("Strict Focus is on")
                Button("Pause Strict Focus") {
                    appState.pauseFocusEnforcement()
                }
            }
            Button("Open Study Space") {
                openWindow(id: "session")
                NSApp.activate(ignoringOtherApps: true)
            }
            Button("Add Task") {
                isAddingSessionTask = true
            }
            Button("Open Study Setup") {
                guard let box = activeSession?.box else { return }
                let results = ResourceLauncher.shared.openEnabledResources(for: box)
                menuLaunchMessage = results.contains { $0.status == .failed } ? "Some resources failed to open" : "Opened study setup"
            }
            Button("End Session") {
                guard let activeSession else { return }
                SessionManager.endSession(activeSession, notes: activeSession.notes, modelContext: modelContext)
                appState.endSession()
            }
            activeSessionTaskControls
            if let menuLaunchMessage {
                Text(menuLaunchMessage)
            }
            Divider()
        }

        if let resumeBox {
            Button("Resume Study") {
                appState.startSession(boxID: resumeBox.id)
                openDashboard()
            }
        }

        if activeBoxes.isEmpty {
            Text("Create a Study Box to start sessions")
        } else {
            Menu("Start Study Session") {
                ForEach(activeBoxes.prefix(8)) { box in
                    Button(box.name) {
                        appState.startSession(boxID: box.id)
                        openDashboard()
                    }
                }
            }
        }

        Divider()

        Button("Open Dashboard") {
            openDashboard()
        }

        let todayTasks = activeBoxes.flatMap(\.tasks).filter { task in
            TaskManager.filteredTasks([task], filter: .today).isEmpty == false
        }

        Text("Today")
        if todayTasks.isEmpty {
            Text("No urgent tasks")
        } else {
            ForEach(todayTasks.prefix(5)) { task in
                Button(todayTaskTitle(task)) {
                    if let box = task.box {
                        appState.openBox(box.id)
                    }
                    openDashboard()
                }
            }
        }

        Divider()
        Button("Settings") {
            openSettings()
            NSApp.activate(ignoringOtherApps: true)
        }

        Button("Quit Study Boxes") {
            NSApp.terminate(nil)
        }
        .sheet(isPresented: $isAddingSessionTask) {
            if let box = activeSession?.box {
                TaskEditorView(box: box)
                    .frame(minWidth: 520, minHeight: 620)
            } else {
                ContentUnavailableView("No active session", systemImage: "timer")
                    .frame(minWidth: 360, minHeight: 220)
            }
        }
    }

    private func openDashboard() {
        openWindow(id: "dashboard")
        NSApp.activate(ignoringOtherApps: true)
    }

    private func todayTaskTitle(_ task: StudyTask) -> String {
        guard let boxName = task.box?.name else { return task.title }
        return "\(boxName): \(task.title)"
    }

    @ViewBuilder
    private var activeSessionTaskControls: some View {
        Divider()
        Text("Current tasks")

        if activeSession != nil, activeSessionTasks.isEmpty {
            Text("No active tasks")
        } else if let activeSession {
            ForEach(activeSessionTasks.prefix(8)) { task in
                Menu(task.title) {
                    Button {
                        SessionManager.markTaskDone(task, in: activeSession, modelContext: modelContext)
                    } label: {
                        Label("Mark Done", systemImage: "checkmark.circle")
                    }

                    Button {
                        SessionManager.markTaskSkipped(task, in: activeSession, modelContext: modelContext)
                    } label: {
                        Label("Skip", systemImage: "forward.circle")
                    }
                }
            }
        }
    }
}

// MARK: - StudyBoxes/Views/Onboarding/OnboardingView.swift

import SwiftData
import SwiftUI

struct OnboardingView: View {
    @Environment(\.dismiss) private var dismiss
    @Environment(\.modelContext) private var modelContext
    @EnvironmentObject private var appState: AppState

    let onCompleted: (StudyBox?, Bool) -> Void

    @State private var selectedTemplate: StudyBoxTemplate = .weeklyCourse
    @State private var name = ""
    @State private var courseName = ""
    @State private var includeDueDate = false
    @State private var dueDate = Date()
    @State private var websiteText = ""
    @State private var firstTaskTitle = ""
    @State private var selectedFileURL: URL?
    @State private var selectedFolderURL: URL?
    @State private var errorMessage: String?

    var body: some View {
        VStack(alignment: .leading, spacing: 18) {
            header

            ScrollView {
                VStack(alignment: .leading, spacing: 18) {
                    templatePicker
                    detailsSection
                    resourceSection
                    firstTaskSection
                }
                .padding(.vertical, 2)
            }

            if let errorMessage {
                Label(errorMessage, systemImage: "exclamationmark.triangle")
                    .font(.caption)
                    .foregroundStyle(.orange)
            }

            footer
        }
        .padding(24)
        .frame(minWidth: 680, idealWidth: 760, minHeight: 620)
    }

    private var header: some View {
        VStack(alignment: .leading, spacing: 8) {
            Text("Set up your first Study Box")
                .font(.largeTitle.weight(.semibold))
            Text("Pick a starting point, add one or two materials, and you can start studying right away.")
                .font(.callout)
                .foregroundStyle(.secondary)
        }
    }

    private var templatePicker: some View {
        VStack(alignment: .leading, spacing: 10) {
            Text("Choose a template")
                .font(.headline)

            LazyVGrid(columns: [GridItem(.adaptive(minimum: 190), spacing: 10)], spacing: 10) {
                ForEach(StudyBoxTemplate.allCases) { template in
                    Button {
                        selectedTemplate = template
                    } label: {
                        VStack(alignment: .leading, spacing: 8) {
                            HStack {
                                Image(systemName: template.systemImage)
                                    .foregroundStyle(Color(hex: template.colorHex))
                                Spacer()
                                if selectedTemplate == template {
                                    Image(systemName: "checkmark.circle.fill")
                                        .foregroundStyle(.tint)
                                }
                            }
                            Text(template.title)
                                .font(.headline)
                                .foregroundStyle(.primary)
                            Text(template.subtitle)
                                .font(.caption)
                                .foregroundStyle(.secondary)
                                .lineLimit(2)
                        }
                        .padding(12)
                        .frame(maxWidth: .infinity, minHeight: 112, alignment: .topLeading)
                        .background(.quaternary.opacity(selectedTemplate == template ? 0.35 : 0.18), in: RoundedRectangle(cornerRadius: 8))
                        .overlay {
                            RoundedRectangle(cornerRadius: 8)
                                .stroke(selectedTemplate == template ? Color.accentColor : Color.clear, lineWidth: 1.5)
                        }
                    }
                    .buttonStyle(.plain)
                }
            }
        }
    }

    private var detailsSection: some View {
        VStack(alignment: .leading, spacing: 10) {
            Text("Name it")
                .font(.headline)

            Grid(alignment: .leading, horizontalSpacing: 14, verticalSpacing: 12) {
                GridRow {
                    Text("Subject")
                        .foregroundStyle(.secondary)
                    TextField("Probability, Operating Systems, French...", text: $name)
                        .textFieldStyle(.roundedBorder)
                }
                GridRow {
                    Text("Course")
                        .foregroundStyle(.secondary)
                    TextField("Optional course code or class name", text: $courseName)
                        .textFieldStyle(.roundedBorder)
                }
                GridRow {
                    Toggle("Due date", isOn: $includeDueDate)
                        .foregroundStyle(.secondary)
                    DatePicker("", selection: $dueDate, displayedComponents: .date)
                        .labelsHidden()
                        .disabled(!includeDueDate)
                }
            }
        }
    }

    private var resourceSection: some View {
        VStack(alignment: .leading, spacing: 10) {
            Text("Add study materials")
                .font(.headline)

            Grid(alignment: .leading, horizontalSpacing: 14, verticalSpacing: 12) {
                GridRow {
                    Text("Website")
                        .foregroundStyle(.secondary)
                    TextField("https://moodle.example/course/view.php?id=...", text: $websiteText)
                        .textFieldStyle(.roundedBorder)
                }
                GridRow {
                    Text("File")
                        .foregroundStyle(.secondary)
                    pickerRow(url: selectedFileURL, placeholder: "No file selected") {
                        selectedFileURL = FilePicker.chooseFile()
                    }
                }
                GridRow {
                    Text("Folder")
                        .foregroundStyle(.secondary)
                    pickerRow(url: selectedFolderURL, placeholder: "No folder selected") {
                        selectedFolderURL = FilePicker.chooseFolder()
                    }
                }
            }
        }
    }

    private var firstTaskSection: some View {
        VStack(alignment: .leading, spacing: 10) {
            Text("First task")
                .font(.headline)
            TextField("Optional: what should you do first?", text: $firstTaskTitle)
                .textFieldStyle(.roundedBorder)
        }
    }

    private var footer: some View {
        HStack {
            Button("Skip") {
                OnboardingState.shared.complete()
                onCompleted(nil, false)
                dismiss()
            }

            Spacer()

            Button("Create Blank Study Box") {
                createBlank()
            }

            Button {
                createFromTemplate(startImmediately: true)
            } label: {
                Label("Start first session", systemImage: "play.fill")
            }
            .keyboardShortcut(.defaultAction)
        }
    }

    private func pickerRow(url: URL?, placeholder: String, action: @escaping () -> Void) -> some View {
        HStack {
            Text(url?.lastPathComponent ?? placeholder)
                .foregroundStyle(url == nil ? .secondary : .primary)
                .lineLimit(1)
            Spacer()
            Button("Choose", action: action)
        }
    }

    private func createBlank() {
        let box = StudyBoxTemplateService.makeBlankBox(name: name)
        modelContext.insert(box)
        saveAndFinish(box: box, startImmediately: false)
    }

    private func createFromTemplate(startImmediately: Bool) {
        errorMessage = nil
        var resources: [OnboardingResourceDraft] = []

        if !websiteText.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
            guard let normalizedURL = URLValidator.normalizedURLString(websiteText) else {
                errorMessage = "That website does not look like a valid URL."
                return
            }
            resources.append(OnboardingResourceDraft(
                title: URL(string: normalizedURL)?.host ?? "Course website",
                type: .website,
                urlString: normalizedURL
            ))
        }

        if let selectedFileURL {
            resources.append(OnboardingResourceDraft(
                title: selectedFileURL.lastPathComponent,
                type: .file,
                urlString: selectedFileURL.path
            ))
        }

        if let selectedFolderURL {
            resources.append(OnboardingResourceDraft(
                title: selectedFolderURL.lastPathComponent,
                type: .folder,
                urlString: selectedFolderURL.path
            ))
        }

        let box = StudyBoxTemplateService.makeBox(
            template: selectedTemplate,
            name: name,
            courseName: courseName,
            dueDate: includeDueDate ? dueDate : nil,
            firstTaskTitle: firstTaskTitle,
            resources: resources
        )
        modelContext.insert(box)
        saveAndFinish(box: box, startImmediately: startImmediately)
    }

    private func saveAndFinish(box: StudyBox, startImmediately: Bool) {
        do {
            try modelContext.save()
            OnboardingState.shared.complete()
            appState.openBox(box.id)
            onCompleted(box, startImmediately)
            dismiss()
        } catch {
            errorMessage = "Could not save your first Study Box."
        }
    }
}

