// MARK: - StudyBoxes/Views/Resources/ResourceEditorView.swift

import AppKit
import SwiftData
import SwiftUI

struct ResourceEditorView: View {
    @Environment(\.dismiss) private var dismiss
    @Environment(\.modelContext) private var modelContext

    let box: StudyBox
    private let resource: StudyResource?

    @State private var title: String
    @State private var type: ResourceType
    @State private var urlString: String
    @State private var appBundleID: String
    @State private var appPath: String
    @State private var enabledByDefault: Bool
    @State private var errorMessage: String?
    @State private var lastSuggestedURLString: String?

    init(box: StudyBox, resource: StudyResource? = nil) {
        self.box = box
        self.resource = resource
        let initialType = resource?.type ?? .website
        _title = State(initialValue: resource?.title ?? "")
        _type = State(initialValue: initialType == .youtube ? .website : initialType)
        _urlString = State(initialValue: resource?.urlString ?? initialType.defaultURLString ?? "")
        _appBundleID = State(initialValue: resource?.appBundleID ?? "")
        _appPath = State(initialValue: resource?.appPath ?? "")
        _enabledByDefault = State(initialValue: resource?.enabledByDefault ?? true)
        _lastSuggestedURLString = State(initialValue: resource == nil ? initialType.defaultURLString : nil)
    }

    var body: some View {
        VStack(alignment: .leading, spacing: 0) {
            Form {
	                Section("Resource") {
	                    TextField("Title", text: $title)
	                        .help("A short name shown in the resource list.")

	                    Picker("Type", selection: $type) {
	                        ForEach(ResourceType.selectableCases) { type in
	                            Label(type.title, systemImage: type.systemImage).tag(type)
	                        }
	                    }
	                    .help("Choose what Study Boxes should store and how it should open it.")

	                    Toggle("Open automatically when a study session starts", isOn: $enabledByDefault)
	                        .help("Turn this off for optional resources you only want to open manually.")
	                }

                inputSection

                if type == .commandPlaceholder {
                    Text("Command placeholders are copy-only in v1. Study Boxes will not run shell commands automatically.")
                        .foregroundStyle(.secondary)
                }

                if let errorMessage {
                    Text(errorMessage)
                        .foregroundStyle(.red)
                }
            }
            .formStyle(.grouped)
            .onChange(of: type) { _, newType in
                applySuggestedURL(for: newType)
            }

            Divider()

            HStack {
                Spacer()

                Button("Cancel") {
                    dismiss()
                }

                Button(resource == nil ? "Add" : "Save") {
                    save()
                }
                .keyboardShortcut(.defaultAction)
            }
            .padding()
        }
    }

    @ViewBuilder
    private var inputSection: some View {
        switch type {
        case .app:
	            Section("App") {
	                TextField("App path", text: $appPath)
	                    .help("Path to the selected macOS app.")
	                TextField("Bundle ID", text: $appBundleID)
	                    .help("Bundle ID lets Study Boxes recognize this app during focus mode.")

                Button {
                    if let url = AppPicker.chooseApplication() {
                        appPath = url.path
                        appBundleID = AppPicker.bundleIdentifier(for: url) ?? ""
                        if title.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
                            title = url.deletingPathExtension().lastPathComponent
                        }
                    }
	                } label: {
	                    Label("Choose App", systemImage: "app.badge")
	                }
	                .help("Pick an app from your Mac.")
	            }
	        case .file:
	            Section("File") {
	                TextField("File path", text: $urlString)
	                    .help("Path to the file Study Boxes should open.")

                Button {
                    if let url = FilePicker.chooseFile() {
                        urlString = url.path
                        if title.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
                            title = url.lastPathComponent
                        }
                    }
	                } label: {
	                    Label("Choose File", systemImage: "doc.badge.plus")
	                }
	                .help("Pick a PDF, document, exercise sheet, or other file.")
	            }
	        case .folder:
	            Section("Folder") {
	                TextField("Folder path", text: $urlString)
	                    .help("Path to the folder Study Boxes should open.")

                Button {
                    if let url = FilePicker.chooseFolder() {
                        urlString = url.path
                        if title.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
                            title = url.lastPathComponent
                        }
                    }
	                } label: {
	                    Label("Choose Folder", systemImage: "folder.badge.plus")
	                }
	                .help("Pick a course folder, code folder, or notes folder.")
	            }
	        case .notes:
	            Section("Note") {
	                Text("Notes are stored in Study Boxes and are not opened as external files.")
	                    .font(.caption)
	                    .foregroundStyle(.secondary)
	                TextEditor(text: $urlString)
	                    .frame(minHeight: 90)
	            }
	        case .commandPlaceholder:
	            Section("Command Text") {
	                Text("This is a copy-only command placeholder. Study Boxes will not run it.")
	                    .font(.caption)
	                    .foregroundStyle(.secondary)
	                TextEditor(text: $urlString)
	                    .font(.system(.body, design: .monospaced))
	                    .frame(minHeight: 90)
	            }
	        default:
	            Section("Website") {
	                TextField(type.defaultURLString ?? "https://example.com", text: $urlString)
	                    .help("Paste the course site, LMS page, GitHub repo, Overleaf project, or other study link.")
	                Text("Links open in your browser. Study Boxes cannot hide individual browser tabs.")
	                    .font(.caption)
	                    .foregroundStyle(.secondary)
	            }
	        }
    }

    private func save() {
        let trimmedTitle = title.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmedTitle.isEmpty else {
            errorMessage = "Title is required."
            return
        }

        let trimmedURLString = urlString.trimmingCharacters(in: .whitespacesAndNewlines)
        let trimmedAppPath = appPath.trimmingCharacters(in: .whitespacesAndNewlines)
        let trimmedBundleID = appBundleID.trimmingCharacters(in: .whitespacesAndNewlines)

        if type.expectsURL, URLValidator.normalizedURLString(trimmedURLString) == nil {
            errorMessage = "That does not look like a valid URL."
            return
        }

        if type == .file || type == .folder, trimmedURLString.isEmpty {
            errorMessage = "Choose a file or folder first."
            return
        }

        if type == .app, trimmedAppPath.isEmpty && trimmedBundleID.isEmpty {
            errorMessage = "Choose an app or enter a bundle ID."
            return
        }

        if let resource {
            resource.update(
                title: trimmedTitle,
                type: type,
                urlString: storedURLString(from: trimmedURLString),
                appBundleID: trimmedBundleID.isEmpty ? nil : trimmedBundleID,
                appPath: trimmedAppPath.isEmpty ? nil : trimmedAppPath,
                enabledByDefault: enabledByDefault
            )
        } else {
            let resource = StudyResource(
                box: box,
                title: trimmedTitle,
                type: type,
                urlString: storedURLString(from: trimmedURLString),
                appBundleID: trimmedBundleID.isEmpty ? nil : trimmedBundleID,
                appPath: trimmedAppPath.isEmpty ? nil : trimmedAppPath,
                orderIndex: nextOrderIndex,
                enabledByDefault: enabledByDefault
            )
            modelContext.insert(resource)
        }

        box.touch()

        do {
            try modelContext.save()
            dismiss()
        } catch {
            errorMessage = "Could not save this resource."
        }
    }

    private var nextOrderIndex: Int {
        (box.resources.map(\.orderIndex).max() ?? -1) + 1
    }

    private func storedURLString(from input: String) -> String {
        if type.expectsURL {
            return URLValidator.normalizedURLString(input) ?? input
        }
        return input
    }

    private func applySuggestedURL(for newType: ResourceType) {
        guard let suggestedURLString = newType.defaultURLString else {
            lastSuggestedURLString = nil
            return
        }

        let current = urlString.trimmingCharacters(in: .whitespacesAndNewlines)
        let previousSuggestion = lastSuggestedURLString?.trimmingCharacters(in: .whitespacesAndNewlines)
        if current.isEmpty || current == previousSuggestion {
            urlString = suggestedURLString
        }
        lastSuggestedURLString = suggestedURLString
    }
}

// MARK: - StudyBoxes/Views/Resources/ResourceListView.swift

import AppKit
import SwiftData
import SwiftUI
import UniformTypeIdentifiers

struct ResourceListView: View {
    @Environment(\.modelContext) private var modelContext

    let box: StudyBox

    @State private var isAddingResource = false
    @State private var editingResource: StudyResource?
    @State private var launchResults: [ResourceLaunchResult] = []
    @State private var isDropTargeted = false

    private var resources: [StudyResource] {
        box.resources.sorted { $0.orderIndex < $1.orderIndex }
    }

    var body: some View {
        VStack(alignment: .leading, spacing: 14) {
            HStack {
                VStack(alignment: .leading, spacing: 4) {
	                    Text("Resources")
	                        .font(.title2.weight(.semibold))
	                    Text("Add the files, apps, folders, and links that should open when you study this subject.")
	                        .font(.callout)
	                        .foregroundStyle(.secondary)
	                    Text("Websites open in your browser. Study Boxes cannot manage individual browser tabs.")
	                        .font(.caption)
	                        .foregroundStyle(.secondary)
	                }

                Spacer()

                Button {
                    openAll()
	                } label: {
	                    Label("Open Study Setup", systemImage: "arrow.up.forward.app")
	                }
	                .disabled(resources.filter(\.enabledByDefault).isEmpty)
	                .help("Open every enabled resource for this Study Box.")

                Button {
                    isAddingResource = true
	                } label: {
	                    Label("Add Resource", systemImage: "plus")
	                }
	                .help("Add an app, file, folder, website, note, or copy-only command.")
            }

            if resources.isEmpty {
                ContentUnavailableView(
                    "No resources yet",
                    systemImage: "folder.badge.plus",
                    description: Text("Start with a PDF, a folder, or your LMS course link.")
                )
                .frame(maxWidth: .infinity, minHeight: 180)
                .background(.quaternary.opacity(0.25), in: RoundedRectangle(cornerRadius: 8))
            } else {
                VStack(spacing: 0) {
                    ForEach(resources) { resource in
                        ResourceRow(
                            resource: resource,
                            canMoveUp: resource.id != resources.first?.id,
                            canMoveDown: resource.id != resources.last?.id,
                            onOpen: { launchResults = [ResourceLauncher.shared.open(resource)] },
                            onEdit: { editingResource = resource },
                            onDelete: { delete(resource) },
                            onRelink: { relink(resource) },
                            onMoveUp: { move(resource, direction: -1) },
                            onMoveDown: { move(resource, direction: 1) },
                            onSave: save
                        )

                        if resource.id != resources.last?.id {
                            Divider()
                        }
                    }
                }
                .background(.background, in: RoundedRectangle(cornerRadius: 8))
                .overlay {
                    RoundedRectangle(cornerRadius: 8)
                        .stroke(.quaternary)
                }
            }

            if !launchResults.isEmpty {
                launchSummary
            }
        }
        .padding(10)
        .background(isDropTargeted ? Color.accentColor.opacity(0.12) : Color.clear, in: RoundedRectangle(cornerRadius: 8))
        .onDrop(of: [.fileURL], isTargeted: $isDropTargeted) { providers in
            handleDrop(providers)
        }
        .sheet(isPresented: $isAddingResource) {
            AddResourceView(box: box)
                .frame(minWidth: 520, minHeight: 520)
        }
        .sheet(item: $editingResource) { resource in
            ResourceEditorView(box: box, resource: resource)
                .frame(minWidth: 520, minHeight: 520)
        }
    }

    private var launchSummary: some View {
        VStack(alignment: .leading, spacing: 6) {
            Text("Launch results")
                .font(.headline)

            ForEach(launchResults) { result in
                Label(result.resourceTitle, systemImage: icon(for: result.status))
                    .foregroundStyle(color(for: result.status))
                Text(result.message)
                    .font(.caption)
                    .foregroundStyle(.secondary)
            }
        }
        .padding(12)
        .frame(maxWidth: .infinity, alignment: .leading)
        .background(.quaternary.opacity(0.25), in: RoundedRectangle(cornerRadius: 8))
    }

    private func openAll() {
        launchResults = ResourceLauncher.shared.openEnabledResources(for: box)
    }

    private func delete(_ resource: StudyResource) {
        modelContext.delete(resource)
        normalizeOrder()
        save()
    }

    private func relink(_ resource: StudyResource) {
        guard ResourceHealthService.relink(resource) else { return }
        save()
    }

    private func move(_ resource: StudyResource, direction: Int) {
        var ordered = resources
        guard let currentIndex = ordered.firstIndex(where: { $0.id == resource.id }) else { return }
        let targetIndex = currentIndex + direction
        guard ordered.indices.contains(targetIndex) else { return }

        ordered.swapAt(currentIndex, targetIndex)
        for (index, resource) in ordered.enumerated() {
            resource.orderIndex = index
            resource.touch()
        }
        save()
    }

    private func normalizeOrder() {
        for (index, resource) in resources.enumerated() {
            resource.orderIndex = index
        }
    }

    private func save() {
        do {
            box.touch()
            try modelContext.save()
        } catch {
            assertionFailure("Failed to save resource changes: \(error)")
        }
    }

    private func handleDrop(_ providers: [NSItemProvider]) -> Bool {
        var didSchedule = false
        for provider in providers where provider.hasItemConformingToTypeIdentifier(UTType.fileURL.identifier) {
            provider.loadItem(forTypeIdentifier: UTType.fileURL.identifier, options: nil) { item, _ in
                let url = Self.fileURL(from: item)
                Task { @MainActor in
                    guard let url else { return }
                    addDroppedResource(url)
                }
            }
            didSchedule = true
        }
        return didSchedule
    }

    private static func fileURL(from item: NSSecureCoding?) -> URL? {
        if let url = item as? URL {
            return url
        }
        if let data = item as? Data {
            return URL(dataRepresentation: data, relativeTo: nil)
        }
        if let string = item as? String {
            return URL(string: string)
        }
        return nil
    }

    private func addDroppedResource(_ url: URL) {
        let type: ResourceType
        if url.pathExtension == "app" {
            type = .app
        } else {
            var isDirectory: ObjCBool = false
            FileManager.default.fileExists(atPath: url.path, isDirectory: &isDirectory)
            type = isDirectory.boolValue ? .folder : .file
        }

        let resource = StudyResource(
            box: box,
            title: url.deletingPathExtension().lastPathComponent,
            type: type,
            urlString: url.path,
            appBundleID: type == .app ? AppPicker.bundleIdentifier(for: url) : nil,
            appPath: type == .app ? url.path : nil,
            orderIndex: resources.count
        )
        modelContext.insert(resource)
        normalizeOrder()
        save()
    }

    private func icon(for status: ResourceLaunchStatus) -> String {
        switch status {
        case .success: "checkmark.circle"
        case .failed: "exclamationmark.triangle"
        case .skipped: "minus.circle"
        }
    }

    private func color(for status: ResourceLaunchStatus) -> Color {
        switch status {
        case .success: .green
        case .failed: .red
        case .skipped: .secondary
        }
    }
}

private struct ResourceRow: View {
    @Bindable var resource: StudyResource

    let canMoveUp: Bool
    let canMoveDown: Bool
    let onOpen: () -> Void
    let onEdit: () -> Void
    let onDelete: () -> Void
    let onRelink: () -> Void
    let onMoveUp: () -> Void
    let onMoveDown: () -> Void
    let onSave: () -> Void

    var body: some View {
        HStack(spacing: 12) {
            Image(systemName: resource.type.systemImage)
                .font(.title3)
                .frame(width: 28)
                .foregroundStyle(.secondary)

            VStack(alignment: .leading, spacing: 3) {
                Text(resource.title)
                    .font(.headline)
                    .lineLimit(1)

                Text(subtitle)
                    .font(.caption)
                    .foregroundStyle(.secondary)
                    .lineLimit(1)

                if let healthMessage = healthStatus.message {
                    Label(healthMessage, systemImage: "exclamationmark.triangle")
                        .font(.caption)
                        .foregroundStyle(.orange)
                        .lineLimit(2)
                }
            }

            Spacer()

	            Toggle("Open in sessions", isOn: $resource.enabledByDefault)
	                .toggleStyle(.checkbox)
	                .help("When enabled, this resource opens automatically when a study session starts.")
	                .onChange(of: resource.enabledByDefault) {
	                    resource.touch()
	                    onSave()
	                }

            if resource.type == .commandPlaceholder {
                Button {
                    NSPasteboard.general.clearContents()
                    NSPasteboard.general.setString(resource.urlString, forType: .string)
	                } label: {
	                    Label("Copy Command", systemImage: "doc.on.doc")
	                }
	                .help("Copy this command to the clipboard. Study Boxes does not run commands automatically.")
	            } else if resource.type.isLaunchable {
	                Button {
	                    onOpen()
	                } label: {
	                    Label("Open Now", systemImage: "arrow.up.forward")
	                }
	                .help("Open this resource now.")
	            }

            Menu {
                Button("Move Up", action: onMoveUp)
                    .disabled(!canMoveUp)
                Button("Move Down", action: onMoveDown)
                    .disabled(!canMoveDown)
                Divider()
                if healthStatus == .missingPath {
                    Button("Relink", action: onRelink)
                }
                Button("Edit", action: onEdit)
                Button("Delete", role: .destructive, action: onDelete)
	            } label: {
	                Label("More resource actions", systemImage: "ellipsis.circle")
	            }
	            .menuStyle(.borderlessButton)
	            .help("Edit or delete this resource.")
        }
        .padding(12)
    }

    private var subtitle: String {
        switch resource.type {
        case .app:
            return resource.appBundleID ?? resource.appPath ?? "App"
        case .notes:
            return "Note"
        case .commandPlaceholder:
            return "Copy-only command"
        default:
            return resource.urlString
        }
    }

    private var healthStatus: ResourceHealthStatus {
        ResourceHealthService.status(for: resource)
    }
}

// MARK: - StudyBoxes/Views/Sessions/SessionHistoryView.swift

import SwiftUI

struct SessionHistoryView: View {
    let box: StudyBox

    @State private var filter: SessionHistoryFilter = .all

    private var sessions: [StudySession] {
        box.sessions.sorted { $0.startedAt > $1.startedAt }
    }

    private var filteredSessions: [StudySession] {
        sessions.filter { filter.includes($0.startedAt) }
    }

    var body: some View {
        VStack(alignment: .leading, spacing: 14) {
            HStack {
                Text("Session history")
                    .font(.title2.weight(.semibold))
                Spacer()
                Picker("History filter", selection: $filter) {
                    ForEach(SessionHistoryFilter.allCases) { filter in
                        Text(filter.title).tag(filter)
                    }
                }
                .pickerStyle(.segmented)
                .frame(width: 280)
            }

            if sessions.isEmpty {
                ContentUnavailableView(
                    "No sessions yet",
                    systemImage: "clock",
                    description: Text("Start a 25-minute session to track time, notes, completed tasks, and skipped tasks.")
                )
                .frame(maxWidth: .infinity, minHeight: 160)
                .background(.quaternary.opacity(0.25), in: RoundedRectangle(cornerRadius: 8))
            } else if filteredSessions.isEmpty {
                ContentUnavailableView(
                    "No sessions in this period",
                    systemImage: "clock.badge.questionmark",
                    description: Text("Switch filters or start another study session.")
                )
                .frame(maxWidth: .infinity, minHeight: 150)
                .background(.quaternary.opacity(0.25), in: RoundedRectangle(cornerRadius: 8))
            } else {
                progressCards

                VStack(spacing: 0) {
                    ForEach(filteredSessions.prefix(8)) { session in
                        HStack {
                            VStack(alignment: .leading, spacing: 4) {
                                Text(session.startedAt.formatted(date: .abbreviated, time: .shortened))
                                    .font(.headline)
                                Text("\(session.completedTaskIDs.count) done, \(session.skippedTaskIDs.count) skipped")
                                    .font(.caption)
                                    .foregroundStyle(.secondary)
                            }

                            Spacer()

                            Text(DurationFormatter.minutes(session.durationMinutes))
                                .font(.headline)
                        }
                        .padding(12)

                        if session.id != filteredSessions.prefix(8).last?.id {
                            Divider()
                        }
                    }
                }
                .background(.background, in: RoundedRectangle(cornerRadius: 8))
                .overlay {
                    RoundedRectangle(cornerRadius: 8)
                        .stroke(.quaternary)
                }
            }
        }
    }

    private var progressCards: some View {
        let progress = StudyProgressService.summary(for: box)

        return ViewThatFits(in: .horizontal) {
            HStack(spacing: 12) {
                historyStat("Total", DurationFormatter.minutes(progress.totalMinutes))
                historyStat("This week", DurationFormatter.minutes(progress.weekMinutes))
                historyStat("This month", DurationFormatter.minutes(progress.monthMinutes))
                historyStat("Average", DurationFormatter.minutes(progress.averageSessionMinutes))
            }
            VStack(spacing: 12) {
                historyStat("Total", DurationFormatter.minutes(progress.totalMinutes))
                historyStat("This week", DurationFormatter.minutes(progress.weekMinutes))
                historyStat("This month", DurationFormatter.minutes(progress.monthMinutes))
                historyStat("Average", DurationFormatter.minutes(progress.averageSessionMinutes))
            }
        }
    }

    private func historyStat(_ title: String, _ value: String) -> some View {
        VStack(alignment: .leading, spacing: 4) {
            Text(title)
                .font(.caption)
                .foregroundStyle(.secondary)
            Text(value)
                .font(.headline)
        }
        .padding(12)
        .frame(maxWidth: .infinity, alignment: .leading)
        .background(.quaternary.opacity(0.18), in: RoundedRectangle(cornerRadius: 8))
    }
}

enum SessionHistoryFilter: String, CaseIterable, Identifiable {
    case all
    case thisWeek
    case thisMonth

    var id: String { rawValue }

    var title: String {
        switch self {
        case .all: "All"
        case .thisWeek: "Week"
        case .thisMonth: "Month"
        }
    }

    func includes(_ date: Date, now: Date = .now, calendar: Calendar = .current) -> Bool {
        switch self {
        case .all:
            return true
        case .thisWeek:
            guard let start = calendar.dateInterval(of: .weekOfYear, for: now)?.start else { return true }
            return date >= start && date <= now
        case .thisMonth:
            guard let start = calendar.dateInterval(of: .month, for: now)?.start else { return true }
            return date >= start && date <= now
        }
    }
}

// MARK: - StudyBoxes/Views/Sessions/SessionModeView.swift

import AppKit
import SwiftData
import SwiftUI

struct SessionModeView: View {
    @Environment(\.modelContext) private var modelContext
    @EnvironmentObject private var appState: AppState

    let box: StudyBox
    let session: StudySession
    let launchResults: [ResourceLaunchResult]
    var onNotesChanged: (String) -> Void = { _ in }

    @State private var now = Date()
    @State private var notes = ""
    @State private var hasEnded = false
    @State private var isAddingTask = false

    private let timer = Timer.publish(every: 1, on: .main, in: .common).autoconnect()

    private var activeTasks: [StudyTask] {
        TaskManager.sorted(box.tasks.filter { $0.status != .done })
    }

    var body: some View {
        VStack(alignment: .leading, spacing: 0) {
            if hasEnded {
                SessionSummaryView(
                    box: box,
                    session: session,
                    onStartAnother: {
                        appState.endSession()
                        appState.startSession(boxID: box.id)
                    },
                    onBackToDashboard: {
                        appState.endSession()
                    }
                )
            } else {
                ScrollView {
                    sessionBody
                        .frame(maxWidth: .infinity, alignment: .topLeading)
                }
            }
        }
        .onAppear {
            notes = session.notes ?? ""
        }
        .onChange(of: notes) {
            session.notes = notes
            onNotesChanged(notes)
        }
        .onReceive(timer) { date in
            guard session.endedAt == nil else { return }
            now = date
        }
        .sheet(isPresented: $isAddingTask) {
            TaskEditorView(box: box)
                .frame(minWidth: 520, minHeight: 620)
        }
    }

    private var sessionBody: some View {
        ViewThatFits(in: .horizontal) {
            regularSessionBody
            compactSessionBody
        }
        .padding(24)
    }

    private var regularSessionBody: some View {
        VStack(alignment: .leading, spacing: 20) {
            header

            HStack(alignment: .top, spacing: 18) {
                tasksPanel
                    .frame(minWidth: 320)
                    .frame(maxWidth: .infinity, alignment: .topLeading)

                sidePanel
                    .frame(width: 260, alignment: .topLeading)
            }

            Divider()

            HStack {
                notesEditor
                endSessionButton
            }
        }
    }

    private var compactSessionBody: some View {
        VStack(alignment: .leading, spacing: 18) {
            compactHeader
            tasksPanel
            sidePanel
                .frame(maxWidth: .infinity, alignment: .topLeading)
            notesEditor
            endSessionButton
        }
    }

    private var header: some View {
        HStack(alignment: .center) {
            VStack(alignment: .leading, spacing: 6) {
                Text(box.name)
                    .font(.title.weight(.semibold))
                    .lineLimit(1)
                    .minimumScaleFactor(0.75)

                Text("Planned \(DurationFormatter.minutes(session.plannedMinutes))")
                    .foregroundStyle(.secondary)
            }

            Spacer()

            VStack(alignment: .trailing, spacing: 4) {
                Text(DurationFormatter.clock(now.timeIntervalSince(session.startedAt)))
                    .font(.system(size: 38, weight: .semibold, design: .rounded))
                    .monospacedDigit()
                    .lineLimit(1)
                    .minimumScaleFactor(0.65)
                Text("elapsed")
                    .font(.caption)
                    .foregroundStyle(.secondary)
                if appState.isHidingDistractionsActive {
                    Label("Apps hidden", systemImage: "eye.slash")
                        .font(.caption)
                        .foregroundStyle(.secondary)
                }
                if appState.isFocusEnforcementActive {
                    Button("Pause Strict Focus") {
                        appState.pauseFocusEnforcement()
                    }
                    .font(.caption)
                    .help("Emergency stop: stop closing newly opened apps for this session.")
                }
            }
        }
    }

    private var compactHeader: some View {
        VStack(alignment: .leading, spacing: 10) {
            Text(box.name)
                .font(.title2.weight(.semibold))
                .lineLimit(1)
                .minimumScaleFactor(0.75)

            HStack(alignment: .lastTextBaseline) {
                Text(DurationFormatter.clock(now.timeIntervalSince(session.startedAt)))
                    .font(.system(size: 32, weight: .semibold, design: .rounded))
                    .monospacedDigit()
                    .lineLimit(1)
                    .minimumScaleFactor(0.65)
                Text("elapsed")
                    .font(.caption)
                    .foregroundStyle(.secondary)
                Spacer()
                Text("Planned \(DurationFormatter.minutes(session.plannedMinutes))")
                    .foregroundStyle(.secondary)
            }

            if appState.isHidingDistractionsActive {
                Label("Apps hidden", systemImage: "eye.slash")
                    .font(.caption)
                    .foregroundStyle(.secondary)
            }

            if appState.isFocusEnforcementActive {
                Button("Pause Strict Focus") {
                    appState.pauseFocusEnforcement()
                }
                .font(.caption)
            }
        }
    }

    private var tasksPanel: some View {
        VStack(alignment: .leading, spacing: 10) {
            HStack {
                Text("Current tasks")
                    .font(.headline)
                Spacer()
                Button {
                    isAddingTask = true
                } label: {
                    Label("Add Task", systemImage: "plus")
                }
                .controlSize(.small)
                .help("Add a task without ending this study session.")
            }

            if activeTasks.isEmpty {
                ContentUnavailableView(
                    "No active tasks",
                    systemImage: "checkmark.circle",
                    description: Text("You can still use the resources and save notes for this session.")
                )
                .frame(maxWidth: .infinity, minHeight: 220)
            } else {
                ScrollView {
                    LazyVStack(spacing: 0) {
                        ForEach(activeTasks) { task in
                            SessionTaskRow(
                                task: task,
                                onDone: {
                                    SessionManager.markTaskDone(task, in: session, modelContext: modelContext)
                                },
                                onSkip: {
                                    SessionManager.markTaskSkipped(task, in: session, modelContext: modelContext)
                                }
                            )

                            if task.id != activeTasks.last?.id {
                                Divider()
                            }
                        }
                    }
                }
                .frame(minHeight: 240)
                .background(.background, in: RoundedRectangle(cornerRadius: 8))
                .overlay {
                    RoundedRectangle(cornerRadius: 8)
                        .stroke(.quaternary)
                }
            }
        }
    }

    private var sidePanel: some View {
        VStack(alignment: .leading, spacing: 18) {
            VStack(alignment: .leading, spacing: 10) {
                Text("Resources")
                    .font(.headline)

                ForEach(box.resources.sorted { $0.orderIndex < $1.orderIndex }.prefix(8)) { resource in
                    HStack(spacing: 8) {
                        Image(systemName: resource.type.systemImage)
                            .foregroundStyle(.secondary)
                        Text(resource.title)
                            .lineLimit(1)
                        Spacer()
                        if resource.type == .commandPlaceholder {
                            Button {
                                NSPasteboard.general.clearContents()
                                NSPasteboard.general.setString(resource.urlString, forType: .string)
                            } label: {
                                Image(systemName: "doc.on.doc")
                            }
                            .buttonStyle(.borderless)
                            .help("Copy this command. Study Boxes does not run commands automatically.")
                        } else if resource.type.isLaunchable {
                            Button {
                                _ = ResourceLauncher.shared.open(resource)
                            } label: {
                                Image(systemName: "arrow.up.forward")
                            }
                            .buttonStyle(.borderless)
                            .help("Open this resource now.")
                        }
                    }
                    .font(.callout)
                }

                if box.resources.isEmpty {
                    Text("No resources in this box yet.")
                        .font(.callout)
                        .foregroundStyle(.secondary)
                }
            }

            if !launchResults.isEmpty {
                VStack(alignment: .leading, spacing: 8) {
                    Text(launchResults.contains { $0.status == .failed } ? "Launch issues" : "Opened")
                        .font(.headline)

                    ForEach(launchResults.prefix(6)) { result in
                        Label {
                            VStack(alignment: .leading, spacing: 2) {
                                Text(result.resourceTitle)
                                    .lineLimit(1)
                                if result.status != .success {
                                    Text(result.message)
                                        .font(.caption2)
                                        .foregroundStyle(.secondary)
                                        .lineLimit(2)
                                }
                            }
                        } icon: {
                            Image(systemName: icon(for: result.status))
                        }
                            .font(.caption)
                            .foregroundStyle(color(for: result.status))
                    }
                }
            }

            if !appState.activeStartupIssueMessages.isEmpty || appState.activeWindowRestoreSummary != nil {
                VStack(alignment: .leading, spacing: 8) {
                    Text(appState.activeStartupIssueMessages.isEmpty ? "Workspace report" : "Workspace issues")
                        .font(.headline)

                    if let summary = appState.activeWindowRestoreSummary {
                        Text(summary)
                            .font(.caption)
                            .foregroundStyle(.secondary)
                    }

                    ForEach(appState.activeStartupIssueMessages.prefix(5), id: \.self) { message in
                        Label(message, systemImage: "exclamationmark.triangle")
                            .font(.caption)
                            .foregroundStyle(.orange)
                    }
                }
            }

            Text("Browsers are treated as one app. Study Boxes opens study websites but does not manage individual tabs.")
                .font(.caption)
                .foregroundStyle(.secondary)
        }
        .padding(14)
        .background(.quaternary.opacity(0.25), in: RoundedRectangle(cornerRadius: 8))
    }

    private var notesEditor: some View {
        ZStack(alignment: .topLeading) {
            TextEditor(text: $notes)
                .font(.body)
                .scrollContentBackground(.hidden)

            if notes.isEmpty {
                Text("Quick notes")
                    .font(.body)
                    .foregroundStyle(.secondary)
                    .padding(.leading, 4)
                    .allowsHitTesting(false)
            }
        }
        .frame(minHeight: 96)
        .background(.background.opacity(0.35), in: RoundedRectangle(cornerRadius: 8))
    }

    private var endSessionButton: some View {
        HStack {
            Spacer()
            Button(role: .destructive) {
                SessionManager.endSession(session, notes: notes, modelContext: modelContext)
                hasEnded = true
            } label: {
                Label("End Session", systemImage: "stop.circle")
            }
            .controlSize(.large)
        }
    }

    private func icon(for status: ResourceLaunchStatus) -> String {
        switch status {
        case .success: "checkmark.circle"
        case .failed: "exclamationmark.triangle"
        case .skipped: "minus.circle"
        }
    }

    private func color(for status: ResourceLaunchStatus) -> Color {
        switch status {
        case .success: .green
        case .failed: .red
        case .skipped: .secondary
        }
    }
}

private struct SessionTaskRow: View {
    let task: StudyTask
    let onDone: () -> Void
    let onSkip: () -> Void

    var body: some View {
        HStack(alignment: .top, spacing: 12) {
            VStack(alignment: .leading, spacing: 5) {
                Text(task.title)
                    .font(.headline)

                HStack(spacing: 8) {
                    Text(task.type.title)
                    if let estimatedMinutes = task.estimatedMinutes {
                        Text("\(estimatedMinutes) min")
                    }
                    if let unit = task.unit {
                        Text(unit)
                    }
                }
                .font(.caption)
                .foregroundStyle(.secondary)

                if let details = task.details, !details.isEmpty {
                    Text(details)
                        .font(.callout)
                        .foregroundStyle(.secondary)
                        .lineLimit(2)
                }
            }

            Spacer()

            Button("Skip", action: onSkip)
            Button {
                onDone()
            } label: {
                Label("Done", systemImage: "checkmark")
            }
        }
        .padding(12)
    }
}

// MARK: - StudyBoxes/Views/Sessions/SessionSetupView.swift

import SwiftUI

struct SessionSetupView: View {
    @Environment(\.dismiss) private var dismiss

    let box: StudyBox
    let onStart: (SessionStartOptions) -> Void

    @State private var plannedMinutes: Int
    @State private var plannedMinutesText: String
    @State private var openResources: Bool
    @State private var hideDistractions: Bool
    @State private var quitDistractions: Bool
    @State private var enforceFocus: Bool
    @State private var restoreWindowLayout: Bool
    @State private var keepDisplayAwake: Bool
    @ObservedObject private var permissions = PermissionManager.shared

    init(box: StudyBox, onStart: @escaping (SessionStartOptions) -> Void) {
        self.box = box
        self.onStart = onStart
        _plannedMinutes = State(initialValue: box.defaultSessionMinutes)
        _plannedMinutesText = State(initialValue: String(box.defaultSessionMinutes))
        _openResources = State(initialValue: box.openResourcesOnSessionStart)
        _hideDistractions = State(initialValue: box.hideDistractionsOnSessionStart)
        _quitDistractions = State(initialValue: box.quitDistractionsOnSessionStart)
        _enforceFocus = State(initialValue: box.enforceFocusOnSessionStart)
        _restoreWindowLayout = State(initialValue: box.restoreWindowLayoutOnSessionStart)
        _keepDisplayAwake = State(initialValue: box.keepDisplayAwakeDuringSessions ?? true)
    }

    var body: some View {
        VStack(alignment: .leading, spacing: 18) {
            VStack(alignment: .leading, spacing: 6) {
                Text("Start Study Session")
                    .font(.title2.weight(.semibold))
                Text(box.name)
                    .foregroundStyle(.secondary)
            }

            Form {
                Section("Plan") {
                    HStack {
                        Text("Presets")
                        Spacer()
                        ForEach(SessionPreset.defaultMinutes, id: \.self) { minutes in
                            Button("\(minutes)") {
                                plannedMinutesText = String(minutes)
                                plannedMinutes = minutes
                            }
                            .controlSize(.small)
                        }
                    }

                    HStack {
                        Text("Session length")
                        Spacer()
                        HStack(spacing: 6) {
                            TextField("0", text: $plannedMinutesText)
                                .frame(width: 56)
                                .multilineTextAlignment(.trailing)
                                .textFieldStyle(.roundedBorder)
                            Text("min")
                                .foregroundStyle(.secondary)
                        }
                    }
                    .help("Type any whole-minute session length up to 999 minutes.")
                    .onChange(of: plannedMinutesText) { _, newValue in
                        let sanitized = NumericInput.sanitizedIntegerText(newValue, range: 0...999)
                        if sanitized != newValue {
                            plannedMinutesText = sanitized
                        }
                        plannedMinutes = NumericInput.integerValue(from: sanitized, fallback: plannedMinutes, range: 0...999)
                    }
                }

                Section("On Start") {
                    Toggle(isOn: $openResources) {
                        Label("Open enabled resources", systemImage: "folder")
                    }
                    Toggle(isOn: $hideDistractions) {
                        Label("Hide unrelated apps", systemImage: "eye")
                    }
                    Toggle(isOn: $quitDistractions) {
                        Label("Ask unrelated apps to quit", systemImage: "xmark.app")
                    }
                    Text("Quit is polite, not force quit. Apps with unsaved work may ask before closing.")
                        .font(.caption)
                        .foregroundStyle(.secondary)
                    Toggle(isOn: $enforceFocus) {
                        Label("Block newly opened distractions", systemImage: "lock.shield")
                    }
                    Toggle(isOn: $restoreWindowLayout) {
                        Label("Restore saved window layout", systemImage: "macwindow")
                    }
                    .disabled(!permissions.isAccessibilityTrusted)
                    Toggle(isOn: $keepDisplayAwake) {
                        Label("Keep display awake", systemImage: "display")
                    }

                    if !permissions.isAccessibilityTrusted {
                        Text("Window layout restore needs Accessibility permission. You can still start the session and hide unrelated apps.")
                            .font(.caption)
                            .foregroundStyle(.secondary)
                    }
                }
            }
            .formStyle(.grouped)

            HStack {
                Spacer()

                Button("Cancel") {
                    dismiss()
                }

                Button {
                    onStart(SessionStartOptions(
                        plannedMinutes: NumericInput.integerValue(from: plannedMinutesText, fallback: plannedMinutes, range: 0...999),
                        openResources: openResources,
                        hideDistractions: hideDistractions,
                        quitDistractions: quitDistractions,
                        enforceFocus: enforceFocus,
                        restoreWindowLayout: restoreWindowLayout,
                        keepDisplayAwake: keepDisplayAwake
                    ))
                } label: {
                    Label("Start", systemImage: "play.fill")
                }
                .keyboardShortcut(.defaultAction)
            }
        }
        .padding(20)
        .frame(minWidth: 420)
        .onAppear {
            permissions.refresh()
            if !permissions.isAccessibilityTrusted {
                restoreWindowLayout = false
            }
        }
        .onChange(of: permissions.isAccessibilityTrusted) { _, isTrusted in
            if !isTrusted {
                restoreWindowLayout = false
            }
        }
    }
}

// MARK: - StudyBoxes/Views/Sessions/SessionSummaryView.swift

import SwiftUI

struct SessionSummaryView: View {
    let box: StudyBox
    let session: StudySession
    let onStartAnother: () -> Void
    let onBackToDashboard: () -> Void

    private var completedTasks: [StudyTask] {
        tasks(matching: session.completedTaskIDs)
    }

    private var skippedTasks: [StudyTask] {
        tasks(matching: session.skippedTaskIDs)
    }

    private var nextTask: StudyTask? {
        StudyResumeService.nextSuggestedTask(for: box)
    }

    var body: some View {
        VStack(alignment: .leading, spacing: 22) {
            VStack(alignment: .leading, spacing: 8) {
                Text("Session saved")
                    .font(.largeTitle.weight(.semibold))
                Text(box.name)
                    .font(.title3)
                    .foregroundStyle(.secondary)
            }

            HStack(alignment: .top, spacing: 14) {
                summaryMetric("Duration", DurationFormatter.minutes(session.durationMinutes), systemImage: "timer")
                summaryMetric("Completed", "\(completedTasks.count)", systemImage: "checkmark.circle")
                summaryMetric("Skipped", "\(skippedTasks.count)", systemImage: "forward.circle")
            }

            taskList(title: "Completed", tasks: completedTasks, emptyText: "No tasks marked done this time.")
            taskList(title: "Skipped", tasks: skippedTasks, emptyText: "No skipped tasks.")

            if let nextTask {
                VStack(alignment: .leading, spacing: 8) {
                    Text("Next up")
                        .font(.headline)
                    Label(nextTask.title, systemImage: nextTask.type.systemImageName)
                        .foregroundStyle(.secondary)
                }
                .padding(14)
                .frame(maxWidth: .infinity, alignment: .leading)
                .background(.quaternary.opacity(0.25), in: RoundedRectangle(cornerRadius: 8))
            }

            if let notes = session.notes, !notes.isEmpty {
                VStack(alignment: .leading, spacing: 8) {
                    Text("Notes")
                        .font(.headline)
                    Text(notes)
                        .foregroundStyle(.secondary)
                }
                .padding(14)
                .frame(maxWidth: .infinity, alignment: .leading)
                .background(.quaternary.opacity(0.25), in: RoundedRectangle(cornerRadius: 8))
            }

            Spacer()

            HStack {
                Spacer()
                Button("Back to dashboard", action: onBackToDashboard)
                Button {
                    onStartAnother()
                } label: {
                    Label("Start another session", systemImage: "play.fill")
                }
                    .keyboardShortcut(.defaultAction)
            }
        }
        .padding(28)
    }

    private func summaryMetric(_ label: String, _ value: String, systemImage: String) -> some View {
        VStack(alignment: .leading, spacing: 8) {
            Label(label, systemImage: systemImage)
                .font(.caption)
                .foregroundStyle(.secondary)
            Text(value)
                .font(.title2.weight(.semibold))
        }
        .padding(14)
        .frame(maxWidth: .infinity, alignment: .leading)
        .background(.quaternary.opacity(0.2), in: RoundedRectangle(cornerRadius: 8))
    }

    private func taskList(title: String, tasks: [StudyTask], emptyText: String) -> some View {
        VStack(alignment: .leading, spacing: 8) {
            Text(title)
                .font(.headline)

            if tasks.isEmpty {
                Text(emptyText)
                    .foregroundStyle(.secondary)
            } else {
                ForEach(tasks) { task in
                    Label(task.title, systemImage: task.type.systemImageName)
                        .foregroundStyle(.secondary)
                }
            }
        }
        .padding(14)
        .frame(maxWidth: .infinity, alignment: .leading)
        .background(.quaternary.opacity(0.2), in: RoundedRectangle(cornerRadius: 8))
    }

    private func tasks(matching ids: [UUID]) -> [StudyTask] {
        ids.compactMap { id in
            box.tasks.first { $0.id == id }
        }
    }
}

private extension StudyTaskType {
    var systemImageName: String {
        switch self {
        case .exercise: "checklist"
        case .theory: "book"
        case .pastExam, .mockExam: "doc.text"
        case .coding: "chevron.left.forwardslash.chevron.right"
        case .review: "arrow.clockwise"
        case .flashcards: "rectangle.stack"
        case .notes: "note.text"
        case .assignment: "doc.badge.clock"
        case .quiz: "questionmark.circle"
        case .other: "circle"
        }
    }
}

// MARK: - StudyBoxes/Views/Sessions/SessionWorkspaceView.swift

import SwiftData
import SwiftUI

struct SessionWorkspaceView: View {
    @Environment(\.modelContext) private var modelContext
    @EnvironmentObject private var appState: AppState

    @Query(sort: \StudySession.startedAt, order: .reverse)
    private var sessions: [StudySession]

    @State private var isEndingFromWindowClose = false

    private var activeSession: StudySession? {
        guard let activeSessionID = appState.activeSessionID else { return nil }
        return sessions.first { $0.id == activeSessionID }
    }

    var body: some View {
        Group {
            if let activeSession, let box = activeSession.box {
                SessionModeView(
                    box: box,
                    session: activeSession,
                    launchResults: appState.activeLaunchResults,
                    onNotesChanged: { notes in
                        activeSession.notes = notes
                    }
                )
                .environmentObject(appState)
            } else {
                ContentUnavailableView(
                    "No active Study Space",
                    systemImage: "rectangle.dashed",
                    description: Text("Start a study session from a Study Box.")
                )
                .frame(minWidth: 760, minHeight: 560)
            }
        }
        .onDisappear {
            endSessionIfWindowClosed()
        }
    }

    private func endSessionIfWindowClosed() {
        guard !isEndingFromWindowClose,
              let activeSession,
              activeSession.endedAt == nil,
              appState.activeSessionID == activeSession.id else {
            return
        }

        isEndingFromWindowClose = true
        SessionManager.endSession(activeSession, notes: activeSession.notes, modelContext: modelContext)
        appState.endSession()
    }
}

// MARK: - StudyBoxes/Views/Settings/AccessibilityOnboardingView.swift

import AppKit
import SwiftUI

struct AccessibilityOnboardingView: View {
    @ObservedObject private var permissions = PermissionManager.shared
    @Environment(\.dismiss) private var dismiss
    @State private var refreshTask: Task<Void, Never>?
    @State private var statusMessage: String?

    var body: some View {
        VStack(alignment: .leading, spacing: 18) {
            Label("Window layout restore needs Accessibility", systemImage: "rectangle.3.group")
                .font(.title2.weight(.semibold))

            Text("Study Boxes needs Accessibility permission to arrange and resize windows for your study workspace.")
                .foregroundStyle(.secondary)

            Text("It does not read your messages or type on your behalf. Without this permission, Study Boxes can still open resources, track tasks, and run sessions.")
                .foregroundStyle(.secondary)

            HStack {
                Label(
                    permissions.isAccessibilityTrusted ? "Permission granted" : "Permission not granted",
                    systemImage: permissions.isAccessibilityTrusted ? "checkmark.circle.fill" : "exclamationmark.circle"
                )
                .foregroundStyle(permissions.isAccessibilityTrusted ? .green : .orange)

                Spacer()
            }
            .padding(12)
            .background(.quaternary.opacity(0.25), in: RoundedRectangle(cornerRadius: 8))

            if let statusMessage {
                Text(statusMessage)
                    .font(.caption)
                    .foregroundStyle(permissions.isAccessibilityTrusted ? .green : .secondary)
            }

            HStack {
                Button("Open System Settings") {
                    statusMessage = "After turning Study Boxes on, come back here and press Check Again."
                    PermissionManager.requestAccessibilityPermission()
                    PermissionManager.openAccessibilitySettings()
                }

                Button("Check Again") {
                    refreshAndDismissIfGranted()
                }

                Button("Continue Without Layout Restore") {
                    dismiss()
                }
                .help("Skip window layout restore. Opening resources, tasks, sessions, and app hiding still work.")

                Spacer()

                Button("Done") {
                    refreshAndDismissIfGranted()
                    if !permissions.isAccessibilityTrusted {
                        dismiss()
                    }
                }
                .keyboardShortcut(.defaultAction)
            }
        }
        .padding(24)
        .onAppear {
            permissions.refresh()
            startRefreshLoop()
        }
        .onReceive(NotificationCenter.default.publisher(for: NSApplication.didBecomeActiveNotification)) { _ in
            permissions.refresh()
            startRefreshLoop()
        }
        .onDisappear {
            refreshTask?.cancel()
            refreshTask = nil
        }
    }

    private func refreshAndDismissIfGranted() {
        permissions.refresh()
        if permissions.isAccessibilityTrusted {
            statusMessage = "Accessibility permission detected."
            dismiss()
        } else {
            statusMessage = "Still not detected. Make sure this exact Study Boxes app is enabled, then quit and reopen Study Boxes if macOS does not refresh it."
        }
    }

    private func startRefreshLoop() {
        refreshTask?.cancel()
        refreshTask = Task {
            for _ in 0..<8 {
                try? await Task.sleep(nanoseconds: 750_000_000)
                guard !Task.isCancelled else { return }
                permissions.refresh()
                if permissions.isAccessibilityTrusted {
                    statusMessage = "Accessibility permission detected."
                    dismiss()
                    return
                }
            }
        }
    }
}

