// MARK: - StudyBoxes/Views/Settings/LicenseView.swift

import AppKit
import SwiftUI

struct LicenseView: View {
    @ObservedObject private var manager = LicenseManager.shared
    @State private var licenseKey = ""
    @FocusState private var isLicenseFieldFocused: Bool

    var body: some View {
        Section("License") {
            VStack(alignment: .leading, spacing: 8) {
                Text(manager.state.title)
                    .font(.headline)
                Text(manager.state.detail)
                    .font(.caption)
                    .foregroundStyle(.secondary)
            }

            HStack(spacing: 8) {
                TextField("License key", text: $licenseKey)
                    .textFieldStyle(.roundedBorder)
                    .focused($isLicenseFieldFocused)
                    .disabled(manager.state == .validating)
                    .onSubmit {
                        activateIfPossible()
                    }

                Button {
                    pasteLicenseKey()
                } label: {
                    Label("Paste", systemImage: "doc.on.clipboard")
                }
                .disabled(manager.state == .validating)

                Button {
                    licenseKey = ""
                    isLicenseFieldFocused = true
                } label: {
                    Label("Clear", systemImage: "xmark.circle")
                }
                .disabled(licenseKey.isEmpty || manager.state == .validating)
            }

            HStack {
                Button("Activate", action: activateIfPossible)
                .disabled(manager.state == .validating || licenseKey.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty)

                Button("Validate") {
                    Task {
                        await manager.validateStoredLicense()
                    }
                }
                .disabled(manager.state == .validating)

                Button("Deactivate", role: .destructive) {
                    Task {
                        await manager.deactivate()
                    }
                }
                .disabled(manager.state == .validating)
            }

            Text("Purchases are not connected in this build. Test keys start with SB-.")
                .font(.caption)
                .foregroundStyle(.secondary)
        }
    }

    private func activateIfPossible() {
        let trimmed = licenseKey.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else {
            isLicenseFieldFocused = true
            return
        }

        Task {
            await manager.activate(licenseKey: trimmed)
            if case .licensed = manager.state {
                licenseKey = ""
            }
        }
    }

    private func pasteLicenseKey() {
        if let pasted = NSPasteboard.general.string(forType: .string) {
            licenseKey = pasted.trimmingCharacters(in: .whitespacesAndNewlines)
        }
        isLicenseFieldFocused = true
    }
}

// MARK: - StudyBoxes/Views/Settings/PermissionsView.swift

import AppKit
import SwiftUI

struct PermissionsView: View {
    @ObservedObject private var permissions = PermissionManager.shared
    @State private var notificationStatus = NotificationPermissionStatus(
        isEnabled: false,
        canRequestInApp: true,
        description: "Checking notification status...",
        canDeliverAlerts: false
    )
    @State private var notificationFeedback: String?
    @State private var isRequestingNotifications = false
    @State private var notificationRefreshTask: Task<Void, Never>?
    @State private var accessibilityFeedback: String?

    var body: some View {
        Section("Permissions") {
            HStack {
                VStack(alignment: .leading) {
                    Text("Notifications")
                    Text("Deadline today, deadline tomorrow, and changed deadline reminders.")
                        .font(.caption)
                        .foregroundStyle(.secondary)
                }
                Spacer()
                Button(notificationButtonTitle) {
                    Task {
                        isRequestingNotifications = true
                        let granted = await NotificationService.requestPermission()
                        await refreshNotificationStatus()
                        notificationFeedback = granted
                            ? "Notifications are enabled."
                            : "Notifications were not enabled. If macOS blocked them, open System Settings and allow Study Boxes."
                        startNotificationStatusRefresh()
                        isRequestingNotifications = false
                    }
                }
                .disabled(notificationStatus.isEnabled || isRequestingNotifications)
            }

            HStack {
                Label(notificationStatus.description, systemImage: notificationStatus.isEnabled ? "checkmark.circle.fill" : "exclamationmark.circle")
                    .font(.caption)
                    .foregroundStyle(notificationStatus.isEnabled ? .green : .secondary)

                Spacer()

                Button("Open Notification Settings") {
                    NotificationService.openNotificationSettings()
                    startNotificationStatusRefresh()
                }
                .buttonStyle(.link)

                Button("Check Again") {
                    Task {
                        await refreshNotificationStatus()
                        notificationFeedback = notificationStatus.canDeliverAlerts
                            ? "Notification delivery is enabled."
                            : notificationStatus.description
                    }
                }
                .buttonStyle(.link)
            }

            if let notificationFeedback {
                Text(notificationFeedback)
                    .font(.caption)
                    .foregroundStyle(notificationStatus.isEnabled ? .green : .secondary)
            }

            HStack {
                VStack(alignment: .leading) {
                    Text("Accessibility")
                    Text("Needed only if you enable best-effort window layout restore.")
                        .font(.caption)
                        .foregroundStyle(.secondary)
                }
                Spacer()
                Button("Open") {
                    accessibilityFeedback = "After enabling Study Boxes in System Settings, press Check Accessibility Again."
                    PermissionManager.requestAccessibilityPermission()
                    PermissionManager.openAccessibilitySettings()
                }
            }

            Text(permissions.isAccessibilityTrusted ? "Accessibility permission granted." : "Accessibility permission not granted.")
                .font(.caption)
                .foregroundStyle(.secondary)

            Button("Check Accessibility Again") {
                permissions.refresh()
                accessibilityFeedback = permissions.isAccessibilityTrusted
                    ? "Accessibility permission detected."
                    : "Still not detected. Make sure this exact Study Boxes app is enabled, then quit and reopen Study Boxes if macOS does not refresh it."
            }

            if let accessibilityFeedback {
                Text(accessibilityFeedback)
                    .font(.caption)
                    .foregroundStyle(permissions.isAccessibilityTrusted ? .green : .secondary)
            }
        }
        .task {
            await refreshNotificationStatus()
            permissions.refresh()
        }
        .onReceive(NotificationCenter.default.publisher(for: NSApplication.didBecomeActiveNotification)) { _ in
            permissions.refresh()
            Task {
                await refreshNotificationStatus()
                startNotificationStatusRefresh()
            }
        }
        .onDisappear {
            notificationRefreshTask?.cancel()
            notificationRefreshTask = nil
        }
    }

    private func refreshNotificationStatus() async {
        notificationStatus = await NotificationService.permissionStatus()
    }

    private var notificationButtonTitle: String {
        if notificationStatus.isEnabled {
            return "Enabled"
        }
        if isRequestingNotifications {
            return "Requesting..."
        }
        return notificationStatus.canRequestInApp ? "Enable" : "Blocked"
    }

    private func startNotificationStatusRefresh() {
        notificationRefreshTask?.cancel()
        notificationRefreshTask = Task {
            let delays: [UInt64] = [
                500_000_000,
                1_500_000_000,
                3_000_000_000,
                5_000_000_000
            ]
            for delay in delays {
                try? await Task.sleep(nanoseconds: delay)
                guard !Task.isCancelled else { return }
                await refreshNotificationStatus()
            }
        }
    }
}

