// MARK: - StudyBoxes/Views/Tasks/TaskEditorView.swift

import SwiftData
import SwiftUI

struct TaskEditorView: View {
    @Environment(\.dismiss) private var dismiss
    @Environment(\.modelContext) private var modelContext

    let box: StudyBox
    private let task: StudyTask?

    @State private var title: String
    @State private var details: String
    @State private var type: StudyTaskType
    @State private var status: StudyTaskStatus
    @State private var priority: Int
    @State private var hasEstimate: Bool
    @State private var estimatedMinutes: Int
    @State private var estimatedMinutesText: String
    @State private var hasDueDate: Bool
    @State private var dueDate: Date
    @State private var unit: String
    @State private var linkedResourceIDs: Set<UUID>
    @State private var subtasksText: String
    @State private var errorMessage: String?

    private var resources: [StudyResource] {
        box.resources.sorted { $0.orderIndex < $1.orderIndex }
    }

    init(box: StudyBox, task: StudyTask? = nil) {
        self.box = box
        self.task = task
        _title = State(initialValue: task?.title ?? "")
        _details = State(initialValue: task?.details ?? "")
        _type = State(initialValue: task?.type ?? .exercise)
        _status = State(initialValue: task?.status ?? .pending)
        _priority = State(initialValue: task?.priority ?? 1)
        _hasEstimate = State(initialValue: task?.estimatedMinutes != nil)
        _estimatedMinutes = State(initialValue: task?.estimatedMinutes ?? 30)
        _estimatedMinutesText = State(initialValue: String(task?.estimatedMinutes ?? 30))
        _hasDueDate = State(initialValue: task?.dueDate != nil)
        _dueDate = State(initialValue: task?.dueDate ?? .now)
        _unit = State(initialValue: task?.unit ?? "")
        _linkedResourceIDs = State(initialValue: Set(task?.linkedResourceIDs ?? []))
        _subtasksText = State(initialValue: task?.subtasks.map(\.title).joined(separator: "\n") ?? "")
    }

    var body: some View {
        VStack(alignment: .leading, spacing: 0) {
            Form {
                Section("Task") {
                    TextField("Title", text: $title)

                    Picker("Type", selection: $type) {
                        ForEach(StudyTaskType.allCases) { type in
                            Text(type.title).tag(type)
                        }
                    }

                    Picker("Status", selection: $status) {
                        ForEach(StudyTaskStatus.allCases) { status in
                            Text(status.title).tag(status)
                        }
                    }

                    Stepper("Priority: \(priorityLabel)", value: $priority, in: 0...3)
                }

                Section("Planning") {
                    TextField("Unit or topic", text: $unit)

                    Toggle("Estimated time", isOn: $hasEstimate)
                    if hasEstimate {
                        HStack {
                            Text("Estimate")
                            Spacer()
                            HStack(spacing: 6) {
                                TextField("0", text: $estimatedMinutesText)
                                    .frame(width: 56)
                                    .multilineTextAlignment(.trailing)
                                    .textFieldStyle(.roundedBorder)
                                Text("minutes")
                                    .foregroundStyle(.secondary)
                            }
                        }
                        .help("Type any whole-minute estimate up to 999 minutes.")
                        .onChange(of: estimatedMinutesText) { _, newValue in
                            let sanitized = NumericInput.sanitizedIntegerText(newValue, range: 0...999)
                            if sanitized != newValue {
                                estimatedMinutesText = sanitized
                            }
                            estimatedMinutes = NumericInput.integerValue(from: sanitized, fallback: estimatedMinutes, range: 0...999)
                        }
                    }

                    Toggle("Due date", isOn: $hasDueDate)
                    if hasDueDate {
                        DatePicker("Date", selection: $dueDate, displayedComponents: .date)
                    }
                }

                Section("Details") {
                    TextEditor(text: $details)
                        .frame(minHeight: 90)
                }

                Section("Subtasks") {
                    Text("One subtask per line.")
                        .font(.caption)
                        .foregroundStyle(.secondary)
                    TextEditor(text: $subtasksText)
                        .frame(minHeight: 72)
                }

                Section("Linked Resources") {
                    if resources.isEmpty {
                        Text("Add resources to this Study Box before linking them to tasks.")
                            .foregroundStyle(.secondary)
                    } else {
                        ForEach(resources) { resource in
                            Toggle(isOn: binding(for: resource.id)) {
                                Label(resource.title, systemImage: resource.type.systemImage)
                            }
                            .help("Show this resource as related context for the task.")
                        }
                    }
                }

                if let errorMessage {
                    Text(errorMessage)
                        .foregroundStyle(.red)
                }
            }
            .formStyle(.grouped)

            Divider()

            HStack {
                Spacer()

                Button("Cancel") {
                    dismiss()
                }

                Button(task == nil ? "Add" : "Save") {
                    save()
                }
                .keyboardShortcut(.defaultAction)
            }
            .padding()
        }
    }

    private var priorityLabel: String {
        switch priority {
        case 0: "Low"
        case 1: "Normal"
        case 2: "Important"
        default: "High"
        }
    }

    private func save() {
        let trimmedTitle = title.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmedTitle.isEmpty else {
            errorMessage = "Title is required."
            return
        }

        let trimmedDetails = details.trimmingCharacters(in: .whitespacesAndNewlines)
        let trimmedUnit = unit.trimmingCharacters(in: .whitespacesAndNewlines)
        let parsedSubtasks = subtasksText
            .components(separatedBy: .newlines)
            .map { $0.trimmingCharacters(in: .whitespacesAndNewlines) }
            .filter { !$0.isEmpty }
            .map { title in
                task?.subtasks.first(where: { $0.title == title }) ?? StudySubtask(title: title)
            }
        let storedEstimatedMinutes = NumericInput.integerValue(
            from: estimatedMinutesText,
            fallback: estimatedMinutes,
            range: 0...999
        )

        if let task {
            task.update(
                title: trimmedTitle,
                details: trimmedDetails.isEmpty ? nil : trimmedDetails,
                type: type,
                status: status,
                priority: priority,
                estimatedMinutes: hasEstimate ? storedEstimatedMinutes : nil,
                dueDate: hasDueDate ? dueDate : nil,
                unit: trimmedUnit.isEmpty ? nil : trimmedUnit,
                linkedResourceIDs: Array(linkedResourceIDs),
                subtasks: parsedSubtasks
            )
        } else {
            let task = StudyTask(
                box: box,
                title: trimmedTitle,
                details: trimmedDetails.isEmpty ? nil : trimmedDetails,
                type: type,
                status: status,
                priority: priority,
                estimatedMinutes: hasEstimate ? storedEstimatedMinutes : nil,
                dueDate: hasDueDate ? dueDate : nil,
                unit: trimmedUnit.isEmpty ? nil : trimmedUnit,
                linkedResourceIDs: Array(linkedResourceIDs),
                subtasks: parsedSubtasks,
                completedAt: status == .done ? .now : nil
            )
            modelContext.insert(task)
        }

        box.touch()

        do {
            try modelContext.save()
            dismiss()
        } catch {
            errorMessage = "Could not save this task."
        }
    }

    private func binding(for resourceID: UUID) -> Binding<Bool> {
        Binding {
            linkedResourceIDs.contains(resourceID)
        } set: { isLinked in
            if isLinked {
                linkedResourceIDs.insert(resourceID)
            } else {
                linkedResourceIDs.remove(resourceID)
            }
        }
    }
}

// MARK: - StudyBoxes/Views/Tasks/TaskListView.swift

import SwiftData
import SwiftUI

struct TaskListView: View {
    @Environment(\.modelContext) private var modelContext

    let box: StudyBox

    @State private var filter: TaskFilter = .today
    @State private var isAddingTask = false
    @State private var editingTask: StudyTask?
    @State private var searchText = ""
    @State private var selectedTaskIDs: Set<UUID> = []

    private var tasks: [StudyTask] {
        TaskManager.searchedTasks(TaskManager.filteredTasks(box.tasks, filter: filter), query: searchText)
    }

    private var pendingCount: Int {
        box.tasks.filter { $0.status == .pending || $0.status == .inProgress }.count
    }

    private var doneCount: Int {
        box.tasks.filter { $0.status == .done }.count
    }

    var body: some View {
        VStack(alignment: .leading, spacing: 14) {
            HStack {
                VStack(alignment: .leading, spacing: 4) {
	                    Text("Tasks")
	                        .font(.title2.weight(.semibold))
	                    Text("\(pendingCount) pending, \(doneCount) done")
	                        .font(.callout)
	                        .foregroundStyle(.secondary)
	                    Text("Use tasks for exercises, readings, review items, and assignment steps.")
	                        .font(.caption)
	                        .foregroundStyle(.secondary)
	                }

                Spacer()

                ViewThatFits(in: .horizontal) {
                    HStack(spacing: 10) {
                        taskControls
                    }
                    VStack(alignment: .trailing, spacing: 8) {
                        taskControls
                    }
                }
            }

            TextField("Search tasks", text: $searchText)
                .textFieldStyle(.roundedBorder)
                .frame(maxWidth: 420)

            if tasks.isEmpty {
                ContentUnavailableView(
                    emptyTitle,
                    systemImage: "checklist",
                    description: Text("Add exercises, review items, theory reading, assignments, or exam practice.")
                )
                .frame(maxWidth: .infinity, minHeight: 180)
                .background(.quaternary.opacity(0.25), in: RoundedRectangle(cornerRadius: 8))
            } else {
                VStack(spacing: 0) {
                    ForEach(tasks) { task in
                        TaskRowView(
                            task: task,
                            isSelected: selectedTaskIDs.contains(task.id),
                            canMoveUp: task.id != tasks.first?.id,
                            canMoveDown: task.id != tasks.last?.id,
                            onSelect: { toggleSelection(task) },
                            onEdit: { editingTask = task },
                            onDelete: { delete(task) },
                            onMoveUp: { move(task, direction: -1) },
                            onMoveDown: { move(task, direction: 1) },
                            onSave: save
                        )

                        if task.id != tasks.last?.id {
                            Divider()
                        }
                    }
                }
                .background(.background, in: RoundedRectangle(cornerRadius: 8))
                .overlay {
                    RoundedRectangle(cornerRadius: 8)
                        .stroke(.quaternary)
                }
            }
        }
        .sheet(isPresented: $isAddingTask) {
            TaskEditorView(box: box)
                .frame(minWidth: 520, minHeight: 560)
        }
        .sheet(item: $editingTask) { task in
            TaskEditorView(box: box, task: task)
                .frame(minWidth: 520, minHeight: 560)
        }
    }

    private var emptyTitle: String {
        switch filter {
        case .all: "No tasks yet"
        case .today: "Nothing urgent for today"
        case .pending: "No pending tasks"
        case .done: "No completed tasks"
        case .highPriority: "No high priority tasks"
        }
    }

    private var taskControls: some View {
        Group {
            Picker("Filter", selection: $filter) {
                ForEach(TaskFilter.allCases) { filter in
                    Text(filter.title).tag(filter)
                }
            }
            .pickerStyle(.segmented)
            .frame(maxWidth: 520)
            .help("Choose which tasks to show in this list.")

            Menu {
                Button("Mark Done") { bulkSetStatus(.done) }
                    .disabled(selectedTaskIDs.isEmpty)
                Button("Mark Pending") { bulkSetStatus(.pending) }
                    .disabled(selectedTaskIDs.isEmpty)
                Button("Skip") { bulkSetStatus(.skipped) }
                    .disabled(selectedTaskIDs.isEmpty)
                Divider()
                Button("Delete Selected", role: .destructive) { bulkDelete() }
                    .disabled(selectedTaskIDs.isEmpty)
            } label: {
                Label("Bulk Actions", systemImage: "checklist.checked")
            }
            .help("Apply a status change or delete selected tasks.")

            Button {
                isAddingTask = true
            } label: {
                Label("Add Task", systemImage: "plus")
            }
            .help("Create a new checklist item for this Study Box.")
        }
    }

    private func delete(_ task: StudyTask) {
        selectedTaskIDs.remove(task.id)
        modelContext.delete(task)
        TaskManager.normalizeOrder(box.tasks)
        save()
    }

    private func toggleSelection(_ task: StudyTask) {
        if selectedTaskIDs.contains(task.id) {
            selectedTaskIDs.remove(task.id)
        } else {
            selectedTaskIDs.insert(task.id)
        }
    }

    private func move(_ task: StudyTask, direction: Int) {
        var ordered = tasks
        guard let currentIndex = ordered.firstIndex(where: { $0.id == task.id }) else { return }
        let targetIndex = currentIndex + direction
        guard ordered.indices.contains(targetIndex) else { return }
        ordered.swapAt(currentIndex, targetIndex)
        for (index, task) in ordered.enumerated() {
            task.orderIndex = index
            task.touch()
        }
        save()
    }

    private func bulkSetStatus(_ status: StudyTaskStatus) {
        for task in box.tasks where selectedTaskIDs.contains(task.id) {
            task.status = status
        }
        selectedTaskIDs.removeAll()
        save()
    }

    private func bulkDelete() {
        for task in box.tasks where selectedTaskIDs.contains(task.id) {
            modelContext.delete(task)
        }
        selectedTaskIDs.removeAll()
        TaskManager.normalizeOrder(box.tasks)
        save()
    }

    private func save() {
        do {
            box.touch()
            try modelContext.save()
        } catch {
            assertionFailure("Failed to save task changes: \(error)")
        }
    }
}

// MARK: - StudyBoxes/Views/Tasks/TaskRowView.swift

import SwiftData
import SwiftUI

struct TaskRowView: View {
    @Bindable var task: StudyTask

    let isSelected: Bool
    let canMoveUp: Bool
    let canMoveDown: Bool
    let onSelect: () -> Void
    let onEdit: () -> Void
    let onDelete: () -> Void
    let onMoveUp: () -> Void
    let onMoveDown: () -> Void
    let onSave: () -> Void

    var body: some View {
        HStack(alignment: .top, spacing: 12) {
            Button(action: onSelect) {
                Image(systemName: isSelected ? "checkmark.square.fill" : "square")
            }
            .buttonStyle(.plain)
            .help(isSelected ? "Remove this task from bulk actions." : "Select this task for bulk actions.")

            statusButton

            VStack(alignment: .leading, spacing: 5) {
                HStack(spacing: 8) {
                    Text(task.title)
                        .font(.headline)
                        .strikethrough(task.status == .done)

                    if task.priority >= 3 {
                        Label("High", systemImage: "exclamationmark.circle.fill")
                            .labelStyle(.iconOnly)
                            .foregroundStyle(.orange)
                    }
                }

                HStack(spacing: 8) {
                    Text(task.type.title)
                    if let unit = task.unit, !unit.isEmpty {
                        Text(unit)
                    }
                    if let estimatedMinutes = task.estimatedMinutes {
                        Text("\(estimatedMinutes) min")
                    }
                    if let dueDate = task.dueDate {
                        Text("Due \(dueDate.formatted(date: .abbreviated, time: .omitted))")
                    }
                }
                .font(.caption)
                .foregroundStyle(.secondary)

                if let details = task.details, !details.isEmpty {
                    Text(details)
                        .font(.callout)
                        .foregroundStyle(.secondary)
                        .lineLimit(2)
                }

                if !task.subtasks.isEmpty {
                    VStack(alignment: .leading, spacing: 3) {
                        ForEach(task.subtasks.prefix(4)) { subtask in
                            Label(subtask.title, systemImage: subtask.isDone ? "checkmark.circle.fill" : "circle")
                                .font(.caption)
                                .foregroundStyle(.secondary)
                        }
                    }
                }
            }

            Spacer()

	            Button("Skip") {
	                task.markSkipped()
	                onSave()
	            }
	            .disabled(task.status == .skipped || task.status == .done)
	            .help("Mark this task as skipped for now. It will not count as completed.")

	            Menu {
                    Button("Move Up", action: onMoveUp)
                        .disabled(!canMoveUp)
                    Button("Move Down", action: onMoveDown)
                        .disabled(!canMoveDown)
                    Divider()
	                Button("Edit Task", action: onEdit)
	                if task.status == .done || task.status == .skipped {
	                    Button("Mark Pending") {
	                        task.markPending()
                        onSave()
                    }
                }
	                Button("Delete", role: .destructive, action: onDelete)
	            } label: {
	                Label("More task actions", systemImage: "ellipsis.circle")
	            }
	            .menuStyle(.borderlessButton)
	            .help("Edit, reset, or delete this task.")
        }
        .padding(12)
    }

    private var statusButton: some View {
        Button {
            if task.status == .done {
                task.markPending()
            } else {
                task.markDone()
            }
            onSave()
	        } label: {
	            Image(systemName: task.status == .done ? "checkmark.circle.fill" : "circle")
	                .font(.title3)
	                .foregroundStyle(task.status == .done ? .green : .secondary)
	        }
	        .buttonStyle(.plain)
	        .help(task.status == .done ? "Mark this task pending again." : "Mark this task done.")
	    }
}
